(window.__BOOKS=window.__BOOKS||{})["e_hecuba"]={"b":[["h2","Действующие лица"],["person","<span class=\"pn\">Тень Полидора, младшего сына Приама и <span class=\"ch\" data-ch=\"gekuba\">Гекубы</span></span> <span class=\"act-no\">(II)</span>"],["person","<span class=\"pn\">Гекуба, вдова троянского царя Приама</span> <span class=\"act-no\">(I)</span>"],["person","<span class=\"pn\">Хор из 15 пленных троянок</span>"],["person","<span class=\"pn\">Поликсена, дочь <span class=\"ch\" data-ch=\"gekuba\">Гекубы</span></span> <span class=\"act-no\">(II)</span>"],["person","<span class=\"pn\">Одиссей, царь Итаки</span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\">Талфибий, ахейский герольд</span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\">Служанка</span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\">Агамемнон, царь аргосский, предводитель ахейской рати</span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\">Полиместор, фракийский царь</span> <span class=\"act-no\">(II)</span>"],["place","Действие в Херсонесе Фракийском, после падения Трои."],["act","Пролог","a1",""],["sd","Предрассветный туман. Побережье моря. Вдали смутно пестреют паруса триер — ахейский стан; на сцене шатер <span class=\"ch\" data-ch=\"agamemnon\">Агамемнона</span>. Около нее появляется тень Полидора."],["scene","Явление первое","s1",1,1],["sp","Тень Полидора"],["v","Приют теней и тяжкие врата",0,1,0,0],["v","Аидовы покинул я, которых",0,1,0,0],["v","Чуждаются и боги. Полидором",0,1,0,0],["v","Меня зовут, и дочерью Киссея,",0,1,0,0],["v","Гекубою, Приаму я рожден.",0,2,0,0],["v","Когда копье ахейское грозило",0,3,0,0],["v","Твердыням Илиона, из своей",0,4,0,0],["v","Отец меня земли троянской к другу",0,5,0,0],["v","Фракийскому в чертог его, таясь,",0,6,0,0],["v","Послал. Над этой гладью <span class=\"ch\" data-ch=\"polimestor\">Полиместор</span>,",0,7,0,0],["v","И для семян пригодной, и коням",0,8,0,0],["v","Отрадною, царит. Немало злата",0,9,0,0],["v","Приам со мной отправил тайно, чтобы,",0,10,0,1],["v","Коль Илион возьмут, нужды его",0,11,0,0],["v","Не видеть детям. Младшего ж из Трои",0,12,0,0],["v","Он удалил, во мне таясь затем,",0,13,0,0],["v","Что ни меча, ни тяжкого доспеха",0,14,0,0],["v","Еще рукой я детской не носил.",0,15,0,0],["v","А здесь, пока ограды стен и башен",0,16,0,0],["v","Нетронуты стояли и копье",0,17,0,0],["v","Не изменяло Гектору, несчастный",0,18,0,0],["v","И брат его, фракийцу мил я был:",0,19,0,0],["v","Как молодой побег, меня лелеял",0,20,0,1],["v","Отцовский гость.",0,20,0,0],["v","Но гибнет Илион.",1,20,0,0],["v","Под солнцем нет и Гектора, и отчий",0,21,0,0],["v","Очаг разбит, а возле алтаря,",0,22,0,0],["v","Хранимого богами, неподвижен",0,22,0,0],["v","Лежит Приам, десницу обагрив",0,23,0,0],["v","Рожденному Пелидом, — и постылым",0,24,0,0],["v","Я делаюсь фракийцу; он меня,",0,25,0,0],["v","Злосчастного, возжаждав злата, солнца",0,25,0,0],["v","Лишает и пучине отдает,",0,26,0,0],["v","Сокровища присвоив.",0,27,0,0],["v","Этот берег —",1,27,0,0],["v","Моя постель. Здесь, пеною морской",0,27,0,0],["v","Да волнами прибоя и отбоя",0,28,0,0],["v","Лелеемый, я насыпи и слез",0,29,0,0],["v","Лишен, увы! Над матерью теперь,",0,30,0,1],["v","Гекубою, воспрянул я, покинув",0,30,0,0],["v","Телесные останки: третий день",0,31,0,0],["v","Прошел, как я убит, и столько ж, Трою",0,32,0,0],["v","На Херсонес сменив, томится дней",0,33,0,0],["v","И мать моя… Недвижим флот союзный",0,34,0,0],["v","У берегов фракийских, и ахейцы",0,35,0,0],["v","В бездействии три дня сидят. Пелид,",0,36,0,0],["v","Над насыпью могильною поднявшись,",0,37,0,0],["v","Остановил движенье весел, жадных",0,38,0,0],["v","До волн отчизны, и сестры моей",0,39,0,0],["v","От воинов он требует, для гроба",0,40,0,1],["v","Отрадной жертвы. И недаром царь",0,41,0,0],["v","Добычи этой ждет: друзья присудят",0,42,0,0],["v","Желанное ему. Сегодня мать",0,43,0,0],["v","Должна двоих детей увидеть трупы —",0,44,0,0],["v","Моей сестры и мой: к ногам рабы",0,45,0,0],["v","Убитого прибьет морская пена.",0,46,0,0],["v","Я умолил властителей глубин",0,47,0,0],["v","Подземных матери прикосновеньем",0,50,0,1],["v","И насыпью могильною мои",0,50,0,0],["v","Почтить останки… и свершится это.",0,51,0,0],["v","Покуда ж пред старыми ее",0,52,0,0],["v","Не покажусь очами я. Атридов",0,52,0,0],["v","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span> дом сейчас покинет: тень",0,53,0,0],["v","Моя во сне царицу испугала…",0,54,0,0],["v","Увы!",0,55,1,0],["v","О мать моя! Царицею заснуть<a class=\"nr\" href=\"#n-k1\" data-n=\"k1\" aria-label=\"Примечание 1\">1</a>",0,55,0,0],["v","И встретить утро в рабской ризе — плата",0,56,0,0],["v","Жестокая за прошлое… Иль бог",0,57,0,0],["v","Какой-нибудь тебя, Гекуба, губит,",0,57,0,0],["v","Что счастья ты познала тяжкий блеск.",0,58,0,0],["sd","(Исчезает. На сцене никого.)"],["sd","Голос <span class=\"ch\" data-ch=\"gekuba\">Гекубы</span> (из шатра)"],["v","О девушки… выйти мне дайте!",0,59,0,0],["v","Поднимите, троянки, рабыню,",0,60,0,1],["v","Что когда-то звали царицей.",0,61,0,0],["v","Вы берите меня, вы ведите меня,",0,62,0,0],["v","Поднимайте за дряхлую руку.",0,63,0,0],["v","На костыль опершись, попытаться хочу",0,64,0,0],["v","Эту сень скорее оставить,",0,65,0,0],["v","Пред дрожащей стопой",0,66,0,0],["v","Подвигая опору.",1,66,0,0],["scene","Явление второе","s2",1,2],["sd","Из шатра в сопровождении нескольких рабынь, которые ее поддерживают, выходит <span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>, опираясь на высокий посох. Ее волосы густы и сплошь в серебряных нитях седины — они подрезаны. Одежда темная и бедная. В темных глазах проблескивают затаившиеся искры."],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","О молнии Зевса! О мрачная ночь!",0,67,0,0],["v","О, зачем среди теней твоих",0,68,0,0],["v","Это виденье?",0,70,0,1],["v","О царица Земля. Возвращаю тебе,",0,71,0,0],["v","Сновидений мать чернокрылых,",0,72,0,0],["v","Призрак ночи, твое исчадье…",0,73,0,0],["v","Сына, который таится во Фракии, дочь <span class=\"ch\" data-ch=\"poliksena\">Поликсену</span>,",0,74,0,0],["v","Милую дочь, ты в виденье, вселяющем ужас холодный,",0,75,0,0],["v","Сердцу явила.",0,76,0,0],["v","О боги земли, спасите мне сына.",0,77,0,0],["v","Нашей ладьи якорь последний,",0,78,0,0],["v","Он один под кровом отчего друга",0,80,0,1],["v","В этой фракийской земле",0,80,0,0],["v","Снеговершинной храним.",0,81,0,0],["v","Новое что-то",0,82,0,0],["v","Близится, точно песня, полная слез,",0,83,0,0],["v","К сердцу, полному слез:",0,84,0,0],["v","Так никогда оно не дрожало",0,85,0,0],["v","Без перерыва от ужаса, сердце мое.",0,85,0,0],["v","Если б, о девы, теперь нам",0,86,0,0],["v","Гелена вечного, если б",0,87,0,0],["v","Сон объяснила Кассандра.",0,88,0,0],["v","Где она, где?",0,89,0,0],["v","Видела: лань я пятнистую будто, к коленям прижавши,",0,90,0,1],["v","Тщетно от волка спасаю — нет жалости в пасти кровавой.",0,90,0,0],["v","А потом… а потом — новый ужас:",0,91,0,0],["v","Над вершиной могильной",0,92,0,0],["v","Встала тень Ахиллеса — она",0,93,0,0],["v","Из троянок несчастных — одной",0,94,0,0],["v","Для гроба просила…",0,95,0,0],["v","О боги! Спасите мое,",0,95,0,0],["v","Мое спасите дитя,",0,96,0,0],["v","Вас молю я, мою <span class=\"ch\" data-ch=\"poliksena\">Поликсену</span>.",0,97,0,0],["scene","Явление третье","s3",1,3],["sd","На орхестру спускается хор из 15 троянских пленниц."],["scene","Вступительная песнь хора","s4",1,4],["sp","Хор"],["v","На крылатых стопах мой покинут шатер:",0,98,0,0],["v","Я украдкой к тебе, Гекуба,",0,99,1,0],["v","От постылого ложа, где жребий меня",0,100,0,1],["v","Оковал, далеко от Трои,<a class=\"nr\" href=\"#n-k3\" data-n=\"k3\" aria-label=\"Примечание 3\">3</a>",0,101,1,0],["v","Ахейца рабыню с злаченым копьем",0,102,0,0],["v","И лова его добычу.",0,103,1,0],["v","Но я бремени муки с тебя не сниму…",0,104,0,0],["v","Мои вести — новое иго,",0,105,1,0],["v","И сама я, царица, — зловещий герольд.",0,106,0,0],["v","На собранье людном данаев,",0,107,1,0],["v","Говорят, решено Ахиллесу твою",0,108,0,0],["v","Дочь зарезать. Слыхала ль: горя",0,109,0,0],["v","Кольчугой, он встал над гробом?",0,110,1,1],["v","Это он и ладьи на волнах удержал, —",0,110,0,0],["v","А у них уж ветрила вздувались тогда,",0,111,0,0],["v","Напрягая канаты, — и царь возопил:",0,112,0,0],["v","\"О, куда ж вы, могилу мою",0,113,0,0],["v","Обделив, куда ж вы, данаи?\"",0,114,0,0],["v","И волны сшибались в пучине вражды,",0,115,0,0],["v","Где эллинов мысли двоились.",0,115,1,0],["v","Одни копьеносцы кричали: \"Дадим",0,116,0,0],["v","Могиле девицу\", другие:",0,117,1,0],["v","«Не надо» — кричали. Меж них",0,118,1,0],["v","И ложе был вещей вакханки твоей<a class=\"nr\" href=\"#n-k4\" data-n=\"k4\" aria-label=\"Примечание 4\">4</a>",0,119,0,0],["v","Почтивший — Атрид <span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>.",0,120,0,1],["v","А против вздымались две ветви младых<a class=\"nr\" href=\"#n-k5\" data-n=\"k5\" aria-label=\"Примечание 5\">5</a>",0,121,0,0],["v","На древе Афины — две речи лились",0,122,0,0],["v","И волей сливались единой.",0,123,1,0],["v","Шумели герои, что надо венчать",0,124,0,0],["v","Могилу свежею кровью;",0,125,1,0],["v","Что стыдно для ложа Кассандры — копье",0,126,0,0],["v","Ахилла унизить, шумели.",0,127,1,0],["v","Но чаши весов колебались еще,",0,130,0,1],["v","Пока сын Лаэрта, чей ум",0,130,1,0],["v","Затейливей ткани узорной,",0,131,1,0],["v","Чьи сладкие речи умеют сердца",0,132,0,0],["v","Мужей уловлять, не вмешался.",0,133,1,0],["v","И так говорил он, внушая мужам:",0,134,0,0],["v","\"Иль лучшему в сонмах Данайских",0,135,1,0],["v","Рабыню убить пожалеем?",0,135,1,0],["v","Смотрите, чтоб мертвый, царице представ",0,136,0,0],["v","Аида, данайцев не назвал,",0,137,1,0],["v","Собратий забывших, которых в Аид",0,138,0,0],["v","Сослала любовь их к Элладе",0,139,1,0],["v","С Троянской равнины\".",0,140,1,1],["v","Сейчас Одиссей, царица, придет…",0,140,0,0],["v","Детеныша он от сосцов",0,141,1,0],["v","Твоих оторвет материнских,",0,142,0,0],["v","Вырвет из старой руки.",0,143,1,0],["v","Иди к кораблям, иди к алтарям!",0,144,0,0],["v","Колени Атрида с мольбой",0,145,1,0],["v","Обняв, призывай ты небесных,",0,146,0,0],["v","Подземных царей заклинай!..",0,147,1,0],["v","И если помогут мольбы,",0,148,1,0],["v","Дочь будет с тобою, Гекуба…",0,149,1,0],["v","Иначе увидеть придется тебе,",0,150,0,1],["v","Как девичья кровь обагряет",0,150,0,0],["v","Вершину могилы",0,151,1,0],["v","И черные реки бегут",0,152,0,0],["v","С золотых ожерелий.<a class=\"nr\" href=\"#n-k2\" data-n=\"k2\" aria-label=\"Примечание 2\">2</a>",0,153,1,0],["act","Действие первое","a2","I"],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["str","Строфа"],["v","О горе! Увы! О, чем отзовусь?",0,154,1,0],["v","Стенаньем каким или плачем?",0,155,1,0],["v","Ты, рабское иго, меня,",0,156,2,0],["v","Ты, ярмо, совсем задавило…",0,157,1,0],["v","О, кто защитит? Какая семья?",0,158,1,0],["v","Иль город какой?",0,159,2,0],["v","Старик — под землей. Ушли сыновья.",0,160,1,1],["v","Куда же я кинусь? Куда?",0,160,2,0],["v","Направо ли брошусь? Налево ль? Куда…",0,161,0,0],["v","Иль бог или демон какой",0,162,2,0],["v","Старухе пособит?",0,163,4,0],["v","Троянки, о вестницы горя,",0,164,2,0],["v","О вестницы мук,",0,165,4,0],["v","Сгубили, убили меня вы —",0,166,2,0],["v","Нет больше под солнцем",0,167,2,0],["v","Мне жизни желанной.",0,168,2,0],["v","Ты, старости жалкий костыль,",0,169,2,0],["v","Веди к ограде старуху,",0,170,2,1],["v","Показывай путь!",0,170,4,0],["v","Дитя мое! дочь",0,171,4,0],["v","Самой несчастной, — о, выйди!",0,172,1,0],["v","Не слышишь? О, какая молва",0,173,2,0],["v","В ушах материнских звучит,",0,174,2,0],["v","Какая молва!",0,175,4,0],["scene","Явление четвертое","s5",2,5],["sd","Из боковых дверей выходит <span class=\"ch\" data-ch=\"poliksena\">Поликсена</span>. Ее руки и шея украшены золотом."],["sp","<span class=\"ch\" data-ch=\"poliksena\">Поликсена</span>"],["v","Ио!",0,176,2,0],["v","О мать моя, мать, зачем я тебе?",0,177,0,0],["v","Точно птенца, ты меня",0,178,2,0],["v","Криком зачем спугнула?",0,179,2,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Горе!<a class=\"nr\" href=\"#n-k6\" data-n=\"k6\" aria-label=\"Примечание 6\">6</a>",0,180,0,1],["sp","<span class=\"ch\" data-ch=\"poliksena\">Поликсена</span>"],["v","Над чем ты? О, черное слово!..",0,181,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Над жизнью… над жизнью твоей…",0,182,0,0],["sp","<span class=\"ch\" data-ch=\"poliksena\">Поликсена</span>"],["v","Не прячь же… Скажи…",0,183,0,0],["v","Робею, поклясться могу,",0,184,0,0],["v","Я этого стона.",0,185,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","О жалкий ребенок…",0,186,0,0],["sp","<span class=\"ch\" data-ch=\"poliksena\">Поликсена</span>"],["v","Ясней, бога ради!",0,187,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Решеньем одним уста их полны —",0,188,0,0],["v","Тебя заколоть на могиле",0,189,0,0],["v","Пелеева сына…",0,190,2,1],["sp","<span class=\"ch\" data-ch=\"poliksena\">Поликсена</span>"],["v","Увы! О мать моя, мать… грозного горя",0,191,0,0],["v","Голос откуда ж в тебе",0,192,2,0],["v","Этот звучит? Горя-то голос?",0,193,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Сказ несказанный — снова услышь:",0,194,0,0],["v","Аргос с тобой,",0,195,2,0],["v","Аргос с тобой порешил…",0,196,0,0],["sp","<span class=\"ch\" data-ch=\"poliksena\">Поликсена</span>"],["dir","после минутной паузы"],["str","Антистрофа"],["v","Страдалица злосчастная о муже,",0,197,0,0],["v","О, горький жребий матери… Опять,",0,198,0,0],["v","Клеймо тебе на сердце разжигая,",0,199,0,0],["v","Демон какой-то кладет…",0,200,2,1],["v","Итак — твой ребенок с тобою,",0,201,0,0],["v","Жалкой и старой,",0,202,2,0],["v","Иго неволи делить",0,203,2,0],["v","Больше не может…",0,204,2,0],["v","Сочной травой ущелий",0,205,0,0],["v","Вскормленную телку",0,206,0,0],["v","От тебя уведут,",0,207,2,0],["v","Из рук твоих вырвут, зарежут",0,208,0,0],["v","Для впадины черной — где мертвых делить",0,209,0,0],["v","Должна я постели…",0,210,2,1],["v","Над долей твоей, моя горькая мать,",0,210,0,0],["v","Я плачу, все стоны — тебе…",0,211,0,0],["v","Своей же позорной и низкой",0,212,0,0],["v","Мне жизни не жалко… И нет для меня",0,213,0,0],["v","Выхода лучше, чем смерть.",0,214,2,0],["scene","Явление пятое","s6",2,6],["sd","Те же и Одиссей с чужой стороны. Одет по-царски, со скипетром и свитой."],["sp","Корифей"],["v","Чу… Одиссей… Как шаг его поспешен!<a class=\"nr\" href=\"#n-k7\" data-n=\"k7\" aria-label=\"Примечание 7\">7</a>",0,215,0,0],["v","К тебе, Гекуба, речь он обратит.",0,216,0,0],["sp","Одиссей"],["dir","к <span class=\"ch\" data-ch=\"gekuba\">Гекубе</span>"],["v","О женщина! Ты волю войсковую",0,217,0,0],["v","И приговор, должно быть, знаешь. Вот",0,218,0,0],["v","Наш приговор: \"Ахейцы присудили",0,219,0,0],["v","Рожденную тобою <span class=\"ch\" data-ch=\"poliksena\">Поликсену</span>",0,220,0,1],["v","Под насыпью Пелида заколоть\".",0,220,0,0],["v","Мы здесь теперь послами от ахейцев,",0,221,0,0],["v","Чтоб увести девицу. А жрецом",0,222,0,0],["v","Пелидов сын назначен ей — надеюсь,",0,223,0,0],["v","Что силою девицу отрывать",0,224,0,0],["v","Не вынудишь меня ты, отбиваясь.",0,225,0,0],["v","Ведь налицо беда-то. Что же тут",0,226,0,0],["v","Поделаешь? А мудрый и в несчастье",0,227,0,0],["v","Рассудка не теряет, говорят…",0,228,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Не миновать беды мне… очень трудной",0,229,0,0],["v","И полной слез борьбы… Так вот зачем",0,230,0,1],["v","Я до сих пор живу, хотя убитой",0,230,0,0],["v","Сто раз бы быть мне, кажется. Меня",0,231,0,0],["v","Доселе Зевс не губит, а питает,",0,232,0,0],["v","Чтоб зрелищем горчайших бед мои",0,233,0,0],["v","Не сытые ль еще глаза насытить…",0,233,0,0],["v","О, коль рабам, царям когда-нибудь",0,234,0,0],["v","Дозволено, их не ужалив речью,",0,235,0,0],["v","Задать вопрос, слова твои моих",0,236,0,0],["v","Ушей теперь, я верю, не минуют.",0,236,0,0],["sp","Одиссей"],["v","Задай вопрос. На время не скуплюсь.",0,237,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Ты помнишь, царь, лазутчиком себя<a class=\"nr\" href=\"#n-k8\" data-n=\"k8\" aria-label=\"Примечание 8\">8</a>",0,238,0,0],["v","Там, в Илионе?.. Лоскутами ризы",0,239,0,0],["v","Обезображен был ты, а из глаз",0,240,0,1],["v","Сочились по ланитам капли крови…",0,241,0,0],["sp","Одиссей"],["v","Глубокий след остался в сердце… Да.",0,242,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Не мне ль одной ты был открыт Еленой?",0,243,0,0],["sp","Одиссей"],["v","В опасности я, точно, был большой.",0,244,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Униженно ты обнял мне колени…",0,245,0,0],["sp","Одиссей"],["v","И рук разжать, казалось, я не мог.",0,246,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Но я дала уйти тебе, ты помнишь?",0,247,0,0],["sp","Одиссей"],["v","Ты это солнце видеть мне дала.",0,248,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","А что сказал ты, раб мой, в те минуты?",0,249,0,0],["sp","Одиссей"],["v","Чтобы спастись, каких не скажешь слов?",0,250,0,1],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Что ж? И тебе не стыдно? Сам признался,",0,250,0,0],["v","Что стольким мне обязан — и не только",0,251,0,0],["v","Не заплатив добром, наоборот,",0,252,0,0],["v","Меня же мучишь, сколько сил хватает.",0,253,0,0],["v","О, семя ненавистное — витии",0,254,0,0],["v","В погоне за отличьем! Никогда бы",0,255,0,0],["v","И не слыхать про вас! В утеху черни",0,256,0,0],["v","Вы губите друзей — и нипочем.<a class=\"nr\" href=\"#n-k9\" data-n=\"k9\" aria-label=\"Примечание 9\">9</a>",0,257,0,0],["v","Я бы хотела знать, какой уловкой",0,258,0,0],["v","Был приговор тот вызван. Может быть,",0,259,0,0],["v","Вам кажется приличнее на гробе",0,260,0,1],["v","Закалывать людей, а не быков?",0,261,0,0],["v","Иль это месть Ахиллова убийцам,",0,262,0,0],["v","И правая, по-вашему? Ребенок",0,263,0,0],["v","Мой ни при чем тут все-таки. Пускай",0,264,0,0],["v","Елены бы потребовал для гроба",0,265,0,0],["v","Заколотой Пелеев сын: она",0,266,0,0],["v","Его влекла под Трою и сгубила…",0,267,0,0],["v","А если меч ваш выбирал красой",0,268,0,0],["v","Меж пленными отмеченную, также",0,269,0,0],["v","На нас он не падет. Тиндара дочь",0,270,0,1],["v","И прелестью всех выше, и рожденьем,",0,270,0,0],["v","Пусть, грешная, не уступает нам.",0,271,0,0],["v","Вот мой ответ, о царь, на вашу правду.",0,272,0,0],["v","Теперь пойми, чего <span class=\"ch\" data-ch=\"gekuba\">Гекуба</span> ждет,",0,272,0,0],["v","Возмездия какого за услугу.",0,273,0,0],["v","Ты подтвердил, что ты руки моей",0,274,0,0],["v","И щек моих с мольбой касался старых,",0,275,0,0],["v","Я то же делаю теперь.",0,275,0,0],["sd","Знаки мольбы. Одиссей стоит довольно спокойно, только слегка пожимая плечами."],["v","И жду",1,275,0,0],["v","Я милости возвратной. Нет, ребенка",0,276,0,0],["v","Не вырывай из рук моих, ножа",0,277,0,0],["v","К ее не подносите шее. Мертвых",0,277,0,0],["v","Вокруг меня с избытком. В ней одна",0,278,0,0],["v","Утеха, царь, и стольких передышка,",0,279,0,0],["v","О, стольких мук… Все в ней одной теперь:",0,280,0,1],["v","И город, и кормилица, и посох,",0,280,0,0],["v","И поводырь. Ты — сильный, только сил",0,281,0,0],["v","Не отдавай дурным страстям. Ты счастлив,",0,282,0,0],["v","Но разве счастье вечно? Вспомни — мой ли",0,283,0,0],["v","Завиден не был жребий? А гляди…",0,284,0,0],["v","День, день один все счастье отнял…",0,285,0,0],["v","Сжалься ж,",1,285,0,0],["v","О борода, молящую почти.<a class=\"nr\" href=\"#n-k10\" data-n=\"k10\" aria-label=\"Примечание 10\">10</a>",0,286,0,0],["v","Ступай назад к ахейцам, объясни им,",0,287,0,0],["v","Разубеди: ведь оскорблять богов,",0,288,0,0],["v","Убивши жен, которых уж когда-то",0,289,0,0],["v","У алтарей простили… Сжалься… Сжальтесь…",0,290,1,1],["v","Свободного ль, раба убить — у вас",0,290,0,0],["v","Ведь равный грех, не правда ли? Ты властен:<a class=\"nr\" href=\"#n-k11\" data-n=\"k11\" aria-label=\"Примечание 11\">11</a>",0,291,0,0],["v","В дурном и то ты убедил бы их…",0,292,0,0],["v","Из царских уст или из уст безвестных",0,293,0,0],["v","Одна и та ж звучит различно речь…",0,294,0,0],["sp","Корифей"],["v","Природы нет такой между людскими",0,295,0,0],["v","Бесчувственной, чтоб на твои стенанья",0,296,0,0],["v","И вопли не ответила слезой.",0,297,0,0],["sp","Одиссей"],["v","Ты ослепить дала себя, Гекуба,",0,298,0,0],["v","Разгневанному сердцу — оттого",0,299,0,0],["v","Разумные слова считаешь злыми.",0,300,0,1],["v","За свой успех готов я уплатить",0,300,0,0],["v","И тою же монетой. Повторяю",0,301,0,0],["v","Тебе слова я эти, но и тех,",0,302,0,0],["v","Произнесенных мною всенародно,",0,303,0,0],["v","Я не возьму назад. А я сказал:",0,304,0,0],["v","\"Когда себе потребовал царевны",0,305,0,0],["v","Тот, между нами первый, так нельзя ж",0,305,0,0],["v","Нам отказать ему\". Не горе это,",0,306,0,0],["v","Когда один почет между людей",0,307,0,0],["v","Что истинно достойному, что прочим.",0,308,0,0],["v","Был истинно достоин Ахиллес,",0,309,0,0],["v","И умер он прекрасно за Элладу.",0,310,0,1],["v","Так не позорно ль было бы ему",0,310,0,0],["v","При жизни льстить, как другу, а едва лишь",0,311,0,0],["v","Глаза закрыть успел — из счета вон.",0,312,0,0],["v","Ведь этак-то, случись опять созыв",0,313,0,0],["v","Военных сил, гляди в глаза сраженье,",0,314,0,0],["v","Пожалуй и задумается кто,",0,315,0,0],["v","Увидевши, какой почет убитым, —",0,316,0,0],["v","Уж выступать ли, полно, поберечь",0,317,0,0],["v","Не лучше ль жизнь? Да взять меня. Покуда",0,318,0,0],["v","Я жив — мне много ль надо? Ну, а гроб",0,319,0,0],["v","Я бы хотел почетный… Нашей славы<a class=\"nr\" href=\"#n-k12\" data-n=\"k12\" aria-label=\"Примечание 12\">12</a>",0,320,0,1],["v","Предел далек…",0,320,0,0],["v","Ты говоришь, жена,",1,320,0,0],["v","Что твой плачевен жребий. Но не меньше",0,321,0,0],["v","Несчастные старухи и у нас,",0,322,0,0],["v","И старики такие ж, и невесты,",0,323,0,0],["v","Чьих женихов покрыла Иды пыль, —",0,324,0,0],["v","Каких мужей покрыла! Духом падать",0,325,0,0],["v","Ты не должна. Пойми: не слыть же нам",0,326,0,0],["v","Невеждами, отказывая мертвым",0,327,0,0],["v","В забвении небрежно. Да, у вас,",0,328,0,0],["v","У варваров, нет уваженья к дружбе,",0,329,0,0],["v","Вас славная не восхищает смерть —",0,330,0,1],["v","Мы ж, эллины, тем держимся. И вот",0,330,0,0],["v","Что принесли, жена, вам ваши мысли.",0,331,0,0],["sp","Корифей"],["v","О рабство! Зла-то что в тебе, увы!",0,332,0,0],["v","Чего, врагом осилена, не терпишь!",0,333,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Увы… О дочь… Бесплодные слова",0,334,0,0],["v","Рассеялись в эфире, нож не спрятан.",0,335,0,0],["v","Искуснее меня ты, может быть,",0,335,0,0],["v","Окажешься… Попробуй, Поликсена!",0,336,0,0],["v","На все лады уста, как соловей,",0,337,0,0],["v","Настраивай, чтоб не лишали жизни.",0,338,0,0],["v","В слезах прильни к его коленям, дочь,",0,339,0,0],["v","Умаливай, — он сам детей имеет:<a class=\"nr\" href=\"#n-k13\" data-n=\"k13\" aria-label=\"Примечание 13\">13</a>",0,340,0,1],["v","Дочерней ли не тронется судьбой?",0,340,0,0],["sp","<span class=\"ch\" data-ch=\"poliksena\">Поликсена</span>"],["dir","видя, что Одиссей отшатнулся и, потупясь, прячет правую руку под плащ"],["v","Я вижу, грек, как под одеждой руку",0,341,0,0],["v","Ты затаил и отвернул лицо:",0,342,0,0],["v","Ты, кажется, боишься, чтоб ланиты",0,343,0,0],["v","С мольбой я не коснулась. Успокойся.",0,343,0,0],["v","И «Зевса нищих» имени не жди —<a class=\"nr\" href=\"#n-k14\" data-n=\"k14\" aria-label=\"Примечание 14\">14</a>",0,344,0,0],["v","Из царских уст. А за тобой пойду я",0,345,0,0],["v","И оттого, что надо, и затем,",0,346,0,0],["v","Что умереть сама хочу. Довольно",0,346,0,0],["v","Вам слабых жен, жизнелюбивых жен.",0,347,0,0],["v","Да и на что мне жить? Престолом мира",0,348,0,0],["v","Фригийского гордился мой отец;",0,349,0,0],["v","Все в жизни ниже власти. Вырастала",0,350,0,1],["v","Я для царей невестой — чей очаг",0,351,0,0],["v","Я пламенем бы оживила, верно,",0,352,0,0],["v","Был зависти б достоин. Между дев",0,353,0,0],["v","Сияла я, как бог — не вечный только.",0,354,0,0],["v","И я — раба… Не правда ль, самый звук,",0,355,0,0],["v","Коль не родился с нами он, то смерти",0,356,0,0],["v","Таит в себе желанье? А господ",0,357,0,0],["v","Узнай-ка нрав заранее! Дикарь",0,358,0,0],["v","Какой-нибудь, купив меня, заставит",0,360,0,1],["v","Варить себе похлебку, дом мести,",0,361,0,0],["v","У челнока поставит ту, что Гектор",0,362,0,0],["v","Сестрою звал и столькие… А день",0,363,0,0],["v","Окончится томительный, и ложе",0,364,0,0],["v","Мне купленный невольник осквернит, —",0,365,0,0],["v","То ложе, что царей манило. Нет!",0,366,0,0],["v","Свободными смежу глаза я, тело",0,367,0,0],["v","Аиду отдавая. Уводи же,",0,368,0,0],["v","И кончите со мною, Одиссей.",0,369,0,0],["v","На лучшее надежды нет, и ждать",0,370,0,1],["v","Мне нечего и незачем бороться.",0,370,0,0],["v","Ты, мать моя, нам не мешай: ни слов,",0,371,0,0],["v","Ни дел твоих не нужно больше; молча",0,372,0,0],["v","Желание дели, чтоб порвалась",0,373,0,0],["v","Цепь жизни и позора. Если губы",0,374,0,0],["v","Еще едва смочила горечь, нам",0,375,0,0],["v","Больнее и ярмо на шею. Право,",0,376,0,0],["v","Счастливее и мертвый иногда,",0,377,0,0],["v","Чем мы, живые. Жить без славы — трудно.",0,378,0,0],["sd","Одиссей стоит, опустив глаза, видимо тронутый словами <span class=\"ch\" data-ch=\"poliksena\">Поликсены</span>."],["sp","Корифей"],["v","О, меж людей на благородном знак",0,379,0,0],["v","И грозный и красивый. Если доблесть",0,380,0,1],["v","В ком светится, на том и знак горит.",0,380,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Слова твои прекрасны, дочь, но горечь",0,381,0,0],["v","В их красоте.",0,382,0,0],["sd","(Одиссею.)"],["v","Коль точно ублажить",0,383,4,0],["v","Пелида вы обязаны, — иначе",0,383,0,0],["v","Упреки ждут аргосцев, — убивать",0,384,0,0],["v","Все ж нет ее причины; отведите",0,385,0,0],["v","К Ахиллову костру меня, колоть",0,386,0,0],["v","<span class=\"ch\" data-ch=\"gekuba\">Гекубу</span> нет запрета вам. Не ею ль",0,386,0,0],["v","Парис зачат, чья горькая стрела",0,387,0,0],["v","Рожденного Фетидой уложила?",0,388,0,0],["sp","Одиссей"],["dir","указывая на <span class=\"ch\" data-ch=\"poliksena\">Поликсену</span>"],["v","Но не тебя, старуха, а ее",0,389,0,0],["v","Потребовал, пойми, Пелидов образ.",0,390,0,1],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Убейте нас тогда обеих — и",0,391,0,0],["v","Кровавою напоите отрадой",0,392,0,0],["v","И землю вы, и мертвеца вдвойне.",0,393,0,0],["sp","Одиссей"],["v","Достаточно одной. Не бойня ж это…",0,394,0,0],["v","И девушку бы, кажется, зачем.",0,395,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","А все ж убить придется вам обеих.",0,396,0,0],["sp","Одиссей"],["dir","мрачно"],["v","Кто ж это мне прикажет, не пойму…",0,397,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["dir","судорожно обнимает <span class=\"ch\" data-ch=\"poliksena\">Поликсену</span>"],["v","Как дуб ее плющом я обмотаю…",0,398,0,0],["sp","Одиссей"],["dir","касаясь ее плеча"],["v","Коль разума лишатся все вокруг.",0,399,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Не выпущу… не выпущу ребенка.",0,400,0,1],["sp","Одиссей"],["dir","со сдержанным, но уже грозным гневом"],["v","Но без нее я тоже не уйду.",0,400,0,0],["sp","<span class=\"ch\" data-ch=\"poliksena\">Поликсена</span>"],["dir","освобождаясь, мягко, но настойчиво"],["v","Родная, успокойся!.. Сын Лаэрта,",0,401,0,0],["v","Она сама себя не помнит… Это ж",0,402,0,0],["v","Понятно… Не сердись… Не надо, мать!",0,403,0,0],["v","Ведь он сильней… Или упасть ты хочешь?",0,404,0,0],["v","Смотри, какие руки. Оттолкнет,",0,405,0,0],["v","И, стукнувшись, ты старое покажешь",0,405,0,0],["v","Уродливо-израненным лицо…",0,406,0,0],["sd","Пауза: несколько секунд молчаливой борьбы."],["v","Где ж удержать тебе меня? На что",0,407,0,0],["v","Надеешься? Довольно унижений.",0,408,0,0],["v","Мне нежную скорее руку дай;",0,409,0,0],["v","В последний раз прижмусь к твоей ланите:",0,410,0,1],["v","Злосчастной, мне не видеть света дня!..",0,410,0,0],["v","Последнему внимаешь ты привету;",0,411,0,0],["v","О мать родная, — в ад я ухожу!",0,412,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","О дочь моя! Увы, рабыней жалкой",0,413,0,0],["v","Богами суждено мне дни влачить!",0,413,0,0],["sp","<span class=\"ch\" data-ch=\"poliksena\">Поликсена</span>"],["v","Уйду в подземный мир одна, и ложе",0,414,0,0],["v","Невесты царской одиноко здесь…",0,415,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Дитя мое! Как за тебя мне горько,",0,416,0,0],["v","Но мать твоя несчастней во сто крат!",0,416,0,0],["sp","<span class=\"ch\" data-ch=\"poliksena\">Поликсена</span>"],["v","В Аиде мне без ласк родимой страшно!",0,417,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Увы! Что делать мне? Как кончить жизнь?",0,418,0,0],["v","<span class=\"ch\" data-ch=\"poliksena\">Поликсена</span>",0,419,4,0],["v","Я — дочь царя, и ухожу — рабыней!",0,420,0,1],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","О, сколько схоронила я детей!",0,420,0,0],["sp","<span class=\"ch\" data-ch=\"poliksena\">Поликсена</span>"],["v","Что мне отцу и Гектору поведать?",0,421,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Что мать твоя — горчайшая из жен…",0,422,0,0],["sp","<span class=\"ch\" data-ch=\"poliksena\">Поликсена</span>"],["v","О грудь, меня вспоившая так сладко!",0,423,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","О дочь, безвременной добыча смерти!",0,423,0,0],["sp","<span class=\"ch\" data-ch=\"poliksena\">Поликсена</span>"],["v","Будь счастлива!.. Прощай и ты, Кассандра!..",0,424,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Я счастья на пути своем не вижу,",0,425,0,0],["v","Оно ушло от матери твоей!",0,426,0,0],["sp","<span class=\"ch\" data-ch=\"poliksena\">Поликсена</span>"],["v","Будь счастлив, Полидор, в степях фракийских!",0,426,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Да, если жив он только… Сердце мне",0,427,0,0],["v","Сомненье гложет, так несчастна я.",0,428,0,0],["sp","<span class=\"ch\" data-ch=\"poliksena\">Поликсена</span>"],["v","Нет, нет! Он жив, я знаю. Полидор",0,429,0,0],["v","В последний час тебе глаза закроет…",0,430,0,1],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Мне горе погасило свет очей!..",0,430,0,0],["sp","<span class=\"ch\" data-ch=\"poliksena\">Поликсена</span>"],["dir","Одиссею, освободившись от матери"],["v","Царь Одиссей, идем, но только мне",0,431,0,0],["v","Лицо завесь, а то, пожалуй, раньше,",0,432,0,0],["v","Чем вы меня заколете, я сердцем",0,432,0,0],["v","Растаю от рыданий материнских",0,433,0,0],["v","Иль изведу слезами мать.",0,434,0,0],["sd","(К солнцу.)"],["v","Тебя",0,434,4,0],["v","Еще назвать могу я, радость солнца,",0,435,0,0],["v","Но свидимся мы разве между медью",0,436,0,0],["v","Ножевою и пламенем костра…",0,436,0,0],["sd","(<span class=\"ch\" data-ch=\"poliksena\">Поликсена</span> спускает вуаль и уходит вместе с Одиссеем и свитой.)"],["scene","Явление шестое","s7",2,7],["v","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span> и хор.",0,437,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["dir","вслед уходящим"],["v","Ой… Лихо… Ухожу я… Факел гаснет…",0,438,0,0],["v","Расходятся суставы… Дочь моя!",0,438,0,0],["v","Возьми меня… Хоть руку дай… Дитя,",0,439,0,0],["v","Не оставляй одну, бездетною… О смерть…",0,440,0,1],["scene","Первый музыкальный антракт","s8",2,8],["sp","Хор"],["str","Строфа I"],["v","Ветер, ветер, дитя морей!",0,441,0,0],["v","Ты по влажным полям несешь",0,442,0,0],["v","Быстрокрылые челны… О,<a class=\"nr\" href=\"#n-k15\" data-n=\"k15\" aria-label=\"Примечание 15\">15</a>",0,443,0,0],["v","О, куда же ты мчишь меня?",0,444,0,0],["v","Где я, горькая, дом найду?",0,445,0,0],["v","Где же купят нас?",0,446,0,0],["v","На дорийских брегах?",0,450,2,1],["v","Иль на фтийских лугах,",0,451,2,0],["v","Где волнами бегут серебристыми",0,452,0,0],["v","Апиданом потоки рожденные?",0,453,0,0],["str","Антистрофа I"],["v","Или жребий мне дом сулил,<a class=\"nr\" href=\"#n-k16\" data-n=\"k16\" aria-label=\"Примечание 16\">16</a>",0,454,0,0],["v","Окруженный волнами дом",0,455,0,0],["v","Для печальной невольницы,",0,456,0,0],["v","Там, где лавра священные",0,457,0,0],["v","С пальмой ветви младой сплелись,",0,458,0,0],["v","Над Латоею ложе мук одев,<a class=\"nr\" href=\"#n-k18\" data-n=\"k18\" aria-label=\"Примечание 18\">18</a>",0,460,2,1],["v","Чтоб меж Делоса дев,",0,461,2,0],["v","Артемида, твою прославляла я",0,462,0,0],["v","Диадему златую и лук златой?",0,463,0,0],["str","Строфа II"],["v","Или в веси Паллады,",0,464,0,0],["v","Девы лучисто-колесной,<a class=\"nr\" href=\"#n-k17\" data-n=\"k17\" aria-label=\"Примечание 17\">17</a><a class=\"nr\" href=\"#n-k19\" data-n=\"k19\" aria-label=\"Примечание 19\">19</a>",0,465,0,0],["v","Нитями пестрыми буду",0,466,0,0],["v","Пеплос ее шафранный<a class=\"nr\" href=\"#n-k20\" data-n=\"k20\" aria-label=\"Примечание 20\">20</a>",0,467,0,0],["v","Я украшать, запрягая",0,468,0,0],["v","Дивной коней в колесницу,",0,470,0,1],["v","Деве рисуя титанов,",0,471,0,0],["v","Зевса перуном пылких,",0,472,0,0],["v","В вечную ночь погруженных.",0,473,0,0],["str","Антистрофа II"],["v","Горе, горе… о дети…",0,474,0,0],["v","Горе… о предки… О Троя!..",0,475,0,0],["v","Ты, о добыча аргосцев,",0,476,0,0],["v","Полная черным дымом,",0,477,0,0],["v","Пламенем полная жадным!",0,478,0,0],["v","Горькое имя рабыни!",0,480,0,1],["v","Вместо небес фригийских —",0,481,0,0],["v","Рабское ложе в Европе…",0,482,0,0],["v","Терем Аида не краше ль?",0,483,0,0],["act","Действие второе","a3","II"],["scene","Явление седьмое","s9",3,9],["sd","Со стороны стана — Талфибий, уже старый глашатай, с царским скипетром."],["sp","Талфибий"],["dir","ищет глазами <span class=\"ch\" data-ch=\"gekuba\">Гекубу</span>, потом хору"],["v","Где бывшую царицу Илиона,",0,484,0,0],["v","О дочери троянские, найду?",0,485,0,0],["sp","Корифей"],["dir","указывая на неподвижную <span class=\"ch\" data-ch=\"gekuba\">Гекубу</span>"],["v","Да вот она, Талфибий, темной ризой",0,486,0,0],["v","Отделена от мира — на земле…",0,487,0,0],["sp","Талфибий"],["dir","после некоторой паузы"],["v","О Зевс! О, что скажу я? Соблюдаешь",0,488,0,0],["v","Ты точно ль нас? Иль даром ты почтен",0,489,0,0],["v","От нас такою славой, а поставлен",0,490,0,1],["v","Над смертными лишь Случай?",0,490,0,0],["v","Здесь, в пыли,",1,490,0,0],["v","Жена царя Приама, златоносных",0,491,0,0],["v","Фригийских гор царица… Эта? Нет!",0,492,0,0],["v","Невольница и дряхлая, детей",0,492,0,0],["v","Пережила она. Пред ней и город",0,493,0,0],["v","Пал, копьями расхищенный, — и вот",0,494,0,0],["v","Она лежит, главою злополучной",0,495,0,0],["v","Мешая пыль. Увы! И я — старик;",0,495,0,0],["v","Но если там, в остатке жизни, скрыта",0,496,0,0],["v","Такая же постыдная судьба,",0,497,0,0],["v","Так умереть бы поскорей…",0,497,0,0],["sd","(Подходит к <span class=\"ch\" data-ch=\"gekuba\">Гекубе</span> и, склонившись над нею -)"],["v","Старуха,",0,498,4,0],["v","Встань, бедная! Ну, хоть приподнимись!..",0,499,0,0],["sd","Пауза."],["v","Хоть голове-то дай расстаться с пылью…",0,500,0,1],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["dir","не вставая"],["v","Кто не дает покоя и убитым?",0,500,0,0],["v","Кто б ни был ты, не рушь меня, скорбящей.",0,501,0,0],["sp","Талфибий"],["v","Талфибий я. Данайский я глашатай,",0,502,0,0],["v","А за тобой <span class=\"ch\" data-ch=\"agamemnon\">Агамемноном</span> послан.",0,503,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["dir","поднимаясь и точно проснувшись"],["v","О лучший друг! Не правда ль, ты принес",0,504,0,0],["v","Решение ахейское — на гробе",0,505,0,0],["v","Зарезать и меня? Как хорошо!",0,505,0,0],["v","О, поспешим! Показывай дорогу.",0,506,0,0],["sp","Талфибий"],["v","Нет, женщина. Я здесь — сопровождать",0,507,0,0],["v","Тебя к твоей покойнице. Ты можешь",0,508,0,0],["v","Похоронить ее. Атриды с тем",0,509,0,0],["v","Меня прислали и народ ахейский.",0,510,0,1],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Так что же я услышу? Значит, смерть",0,511,0,0],["v","Отсрочена опять? О вестник бедствий!",0,512,0,0],["sd","(Закрывает лицо руками. Пауза.)"],["v","И ты, о дочь оторванная, — смертью",0,513,0,0],["v","Сиротство ты усилила мое.",0,514,0,0],["sd","(Пауза. Потом Талфибию.)"],["v","Но кончили вы как же с ней? Была ль",0,515,0,0],["v","Хоть жалость в вас? Иль ужас был и злобен?",0,516,0,0],["v","Хоть горько слышать — все же расскажи.",0,517,0,0],["sp","Талфибий"],["dir","не сразу"],["v","Два дара слез над мертвою… Ну что же?",0,518,0,0],["v","Послу и то награда… Оросят",0,519,0,0],["v","Они лицо опять… И там — я плакал.",0,520,0,1],["v","Громада сил ахейских у холма",0,520,1,0],["v","Ахиллова, где дочь твою для жертвы",0,521,0,0],["v","Готовили, — блистала полнотою.",0,522,0,0],["v","Пелидов сын, касался руки",0,522,0,0],["v","Царевниной, на холм ее поставил.",0,523,0,0],["v","Я, как тебя, теперь их видел. Шли",0,524,0,0],["v","И юноши отборные за ними,",0,525,0,0],["v","Чтоб твоего детеныша держать",0,525,0,0],["v","В минуту содроганий. Следом кубок",0,526,0,0],["v","Из золота литой и полный царь,",0,527,0,0],["v","Обеими руками взяв сначала,",0,527,0,0],["v","Потом одной возносит и отцу",0,528,0,0],["v","Готовится свершить он возлиянье.",0,529,0,0],["v","Он знаком мне велит призвать народ",0,530,0,1],["v","К молчанию, а я, в ряды вмешавшись,",0,530,0,0],["v","Так говорю: \"Молчание… молчи,",0,531,0,0],["v","Ахейский люд… Молчите все…\" Толпа",0,532,0,0],["v","Застыла, как под штилем… Зазвучали",0,533,0,0],["v","Слова Неоптолема: \"О Пелид,",0,534,0,0],["v","О мой отец, те чары, что приводят",0,535,0,0],["v","К нам мертвецов, ты не отринь. Явись",0,536,0,0],["v","Ты девичьей напиться крови чистой;",0,537,0,0],["v","То войска дар и сына. Ты ж за это",0,538,0,0],["v","Открой дорогу кораблям, узду",0,539,0,0],["v","От них вручи ахейцам, чтобы легок",0,540,0,1],["v","Наш был возврат и всем увидеть дом!\"",0,540,0,0],["v","Так вот слова его. А войско кликом",0,541,0,0],["v","Венчало их.",0,542,0,0],["v","Тут, взявшись за эфес,",1,542,0,0],["v","Царь меч извлек сияющий. А свите",0,543,0,0],["v","Отборной он кивает, чтоб схватила",0,543,0,0],["v","Она юницу. Ею царский знак",0,544,0,0],["v","Уловлен был, и речь ее ответом",0,545,0,0],["v","Была к толпе: \"Вы, Аргоса сыны,",0,546,0,0],["v","Что город мой разрушили! Своею",0,546,0,0],["v","Я умираю волей. Пусть никто",0,547,0,0],["v","Меня не держит. Я подставлю горло",0,548,0,0],["v","Без трепета. Но дайте умереть",0,549,0,0],["v","Свободною, богами заклинаю,",0,550,0,1],["v","Как и была свободна я. Сойти",0,551,0,0],["v","Рабынею к теням царевне стыдно\".",0,552,0,0],["v","И смутный гул покрыл слова.",0,553,0,0],["v","А царь",1,553,0,0],["v","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span> сказал: «Освободите».",0,554,0,0],["v","И, царское приявши слово, дочь",0,555,0,0],["v","Приамова от самого плеча",0,556,0,0],["v","И по пояс свой пеплос разорвала,",0,557,0,0],["v","Являя грудь прекрасней изваяний.",0,560,0,1],["v","Потом, к земле склонив колено, так",0,560,0,0],["v","Сказала нам она отважно: \"Вот,",0,561,0,0],["v","О юноша, вот — грудь моя, коль хочешь",0,562,0,0],["v","Разить ее, ударь; а если шеи",0,563,0,0],["v","Возжаждал нож, — мое открыто горло\".",0,564,0,0],["v","И, жалостью объят, Неоптолем,",0,565,0,0],["v","Невольной волей движимый, дыханью",0,565,0,0],["v","Ударом быстрым пресекает путь.",0,566,0,0],["v","Потоком кровь из раны льется. Дева ж —",0,567,0,0],["v","Последний луч — старается упасть",0,568,0,0],["v","Пристойно и скрывает, умирая,",0,569,0,0],["v","То, что должно быть тайной для мужей.",0,570,0,1],["v","Но только вздох последний отдан, мигом",0,571,1,0],["v","В движенье все приходит: те бегут,",0,572,0,0],["v","Умершую листами покрывают,",0,573,0,0],["v","А те костер готовят и еловых",0,574,0,0],["v","Туда несут вязанки сучьев; если ж",0,575,0,0],["v","Кто ничего не делает, тому",0,576,0,0],["v","Со всех сторон кричат: \"Лентяй, негодный!",0,577,0,0],["v","Чего стоишь? Убора ль не припас?",0,578,0,0],["v","Иди сейчас и дар готовь — почтить",0,579,0,0],["v","Великое, бестрепетное сердце\".",0,580,0,1],["v","Вот, женщина, о дочери твоей",0,580,0,0],["v","Что говорили там покойной. Если",0,581,0,0],["v","Между детьми твоих прекрасней нет,",0,582,0,0],["v","Нет и тебя меж матерей несчастней.",0,583,0,0],["sp","Корифей"],["v","Клеймо беды на городе и вас,",0,584,0,0],["v","Рожденные Приамом, боги выжгли.",0,585,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","О дочь!.. Но сколько ж бед передо мною?",0,585,0,0],["v","Коснись одной, — глядишь, впилась другая,",0,586,0,0],["v","А новая к себе влечет… Никак",0,587,0,0],["v","Не выпустят из очереди сердца…",0,588,0,0],["v","Страдание твое с ума нейдет —",0,589,0,0],["v","Я не могу не плакать. А ведь как бы",0,590,0,1],["v","И скорби-то не стихнуть от вестей",0,590,0,0],["v","Такой прекрасной смерти!",0,591,0,0],["v","Если нива",1,591,0,0],["v","С бесплодною землей орошена",0,592,0,0],["v","И вовремя согрета небом, может",0,593,0,0],["v","Она родить сторицей. А другие,",0,593,0,0],["v","И тучные порой, неурожай",0,594,0,0],["v","Постигнет от погоды. Между смертных",0,595,0,0],["v","Совсем не то. Порочный только злым",0,596,0,0],["v","И может быть. А добрый — только добрым:",0,596,0,0],["v","Несчастия не властны извратить",0,597,0,0],["v","Природный дар. Ну, а заслуга чья же?",0,598,0,0],["v","Родивших ли иль тех, кто воспитал?",0,599,0,0],["v","О, воспитанье много значит. Если",0,600,0,1],["v","Кто обучен прекрасному, того",0,600,0,0],["v","Не увлечет постыдное: имеет",0,601,0,0],["v","Он образец в прекрасном.",0,602,0,0],["v","Но зачем",1,602,0,0],["v","Ты мечешь, ум, на воздух эти стрелы?",0,602,0,0],["sd","(Талфибию.)"],["v","Ступай, глашатай, грекам объяви,",0,603,0,0],["v","Чтобы никто до мертвой не касался.",0,604,0,0],["v","Пусть удалят толпу. Средь мириад",0,605,0,0],["v","Бессильна и угроза. А матросы,",0,605,0,0],["v","Да без вождя, — ведь это пламя, хуже",0,606,0,0],["v","Чем пламя; и для них — кто зла бежит,",0,607,0,0],["v","Тот сердцем слаб.",0,607,0,0],["v","Талфибий уходит.",0,608,0,0],["v","Ты, старая слуга,",0,609,4,0],["v","Как встарь, сосуд возьми: с волною моря",0,610,0,1],["v","Края его сравнявши, дашь сюда.",0,610,0,0],["v","Рабыня уходит.",0,611,0,0],["v","Сама хочу последним омовеньем",0,612,0,0],["v","Ее омыть, мое дитя — невесту",0,612,0,0],["v","Без жениха и деву без светлицы;",0,613,0,0],["v","Затем — убрать по мере сил. Достойно",0,614,0,0],["v","Я не могу; не стоит и мечтать.",0,614,0,0],["v","Из украшений женских кое-что",0,615,0,0],["v","У пленниц соберу, товарок в рабстве,",0,616,0,0],["v","Что делят мой шатер. Ведь от господ",0,616,0,0],["v","Припрятала ж иная от недавних",0,617,0,0],["v","Хоть что-нибудь из прежнего добра.",0,618,0,0],["v","О мой чертог, горевший позолотой…",0,618,0,0],["v","Блаженная обитель… Ты, Приам,",0,619,0,0],["v","Отец детей могучих и прекрасных,",0,620,0,1],["v","И я, их мать, — о, как же низко мы,",0,620,0,0],["v","Как глубоко мы с гордой выси пали!",0,621,0,0],["v","Подумаешь, не все ль мы точно гребнем",0,622,0,0],["v","Вздымаемся кичливо: тот — гордясь,",0,623,0,0],["v","Что он богат, а тот — что между граждан",0,624,0,0],["v","В почете он. Какая суета!",0,625,0,0],["v","Заботы эти, замыслы… пустая",0,626,0,0],["v","Шумиха слов. Того зови блаженным,",0,627,0,0],["v","Кому не кроет зла насущный день.",0,628,0,0],["sd","(Уходит в палатку.)"],["scene","Второй музыкальный антракт","s10",3,10],["sp","Хор"],["str","Строфа"],["v","Муку мою решили,",0,629,0,0],["v","Гибель мою написали",0,630,0,1],["v","В день, когда в ель на Иде",0,631,0,0],["v","Париса топор вонзился",0,632,0,0],["v","И он на темные волны",0,633,0,0],["v","Замыслил ладью направить",0,634,0,0],["v","Туда, за Еленой, коей",0,635,0,0],["v","Краше и солнце златое",0,636,0,0],["v","С выси своей не зрело.",0,637,0,0],["str","Антистрофа"],["v","Мука на смену мукам,",0,638,0,0],["v","Цепи цепей тяжелее,",0,640,0,1],["v","И одного безумье",0,640,0,0],["v","Народу стало на гибель.",0,641,0,0],["v","Теперь тот спор пересмотрен,<a class=\"nr\" href=\"#n-k21\" data-n=\"k21\" aria-label=\"Примечание 21\">21</a>",0,642,0,0],["v","Тот спор на лесистой Иде,",0,643,0,0],["v","Когда волопас беспечный",0,644,0,0],["v","Трех обитательниц неба",0,645,0,0],["v","Мыслью судил земною.",0,646,0,0],["str","Эпод"],["v","Он пересмотрен, да —",0,647,0,0],["v","На брань, на кровь, на убийство,",0,648,0,0],["v","На гибель чертогам моим!",0,649,0,0],["v","Но стонут и там,",0,650,0,1],["v","На тихом Евроте,",0,650,0,0],["v","Верно, спартанки:",0,651,0,0],["v","Стонет и плачет дева в дому;",0,652,0,0],["v","Дряхлой рукой терзает",0,653,0,0],["v","Мать там косы седые,",0,654,0,0],["v","Щеки терзает, а кровь",0,655,0,0],["v","По пальцам с ногтей струится.",0,656,0,0],["act","Действие третье","a4","III"],["scene","Явление восьмое","s11",4,11],["sd","Входит старая служанка, которую посылали за водой; она несет тело Полидора, наскоро закутанное в ее троянский пеплос."],["sp","Служанка"],["v","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span> где ж?",0,657,0,0],["sd","(Оглядывается и ищет глазами царицы.)"],["v","Уж точно злополучьем",0,658,4,0],["v","Мужей и жен опередила всех:",0,659,0,0],["v","Никто у ней победы не оспорит.",0,660,0,1],["sp","Корифей"],["v","О, проклят будь зловещий твой язык!",0,661,0,0],["v","И отдыха не знают вести горя.",0,662,0,0],["sp","Служанка"],["v","<span class=\"ch\" data-ch=\"gekuba\">Гекубе</span> скорбь несу: а тем, кто скорбью",0,663,0,0],["v","Застигнут, — тем уж не до благоречья.",0,664,0,0],["sp","Корифей"],["v","Да вот она выходит… И как раз",0,665,0,0],["v","К твоим вестям <span class=\"ch\" data-ch=\"gekuba\">Гекуба</span> подоспела.",0,666,0,0],["scene","Явление девятое","s12",4,12],["sd","Из средней двери — <span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>. За ней женщины несут уборы. Готовится погребальный обряд."],["sp","Служанка"],["dir","<span class=\"ch\" data-ch=\"gekuba\">Гекубе</span>"],["v","Бессчастная превыше слов моих,",0,667,0,0],["v","Погибшая! Уж нет тебя под солнцем,",0,668,0,0],["v","Изгнанница, бездетная, вдова!",0,669,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["dir","мрачно"],["v","Не ново уж. Я знаю все. Молчи!",0,670,0,1],["v","Но труп зачем несешь ты <span class=\"ch\" data-ch=\"poliksena\">Поликсены</span>,",0,670,0,0],["v","Когда мы все слыхали, сколько рук",0,671,0,0],["v","Ахейских ей готовит погребенье?",0,672,0,0],["sp","Служанка"],["v","Не знает… все о <span class=\"ch\" data-ch=\"poliksena\">Поликсене</span> плачет,",0,673,0,0],["v","А новых бед и краем не коснется.",0,674,0,0],["sd","(Кладет труп.)"],["sd","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span> не подходит к нему, издали всматривается в него зорко и беспокойно."],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","О, горе мне! Не девы ль исступленной,",0,675,0,0],["v","Пророчицы Кассандры, тело там?",0,676,0,0],["sp","Служанка"],["v","Она жива.",0,677,0,0],["sd","(Развивая пеплос.)"],["v","Ты ж мертвого оплачь,",0,678,3,0],["v","Вот труп его. Гляди. Дивишься, верно?",0,679,0,0],["v","Ты этого ль, несчастная, ждала?",0,680,0,1],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["dir","в ужасе глядя на сына"],["v","Мертвец — мой сын, мой Полидор; в чертоге",0,680,0,0],["v","Его фракиец для меня берег.",0,681,0,0],["v","Погибла я! Конец, всему конец!",0,682,0,0],["sd","(Приближается к мертвому. Музыка.)"],["v","Мальчик, мальчик мой!",0,683,2,0],["v","Пенясь в безумье,",0,684,2,0],["v","Губы мои поют…",0,685,2,0],["v","Выходец ада<a class=\"nr\" href=\"#n-k22\" data-n=\"k22\" aria-label=\"Примечание 22\">22</a>",0,685,2,0],["v","Песнь мне внушает.",0,686,2,0],["sp","Служанка"],["v","Над сыном грех свершили? Ты узнала?",0,687,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["dir","ломая руки"],["v","Нежданный грех! Неслыханный удар!",0,688,0,0],["v","К горю прежнему",0,689,2,0],["v","Горе новое!",0,690,2,1],["v","Уж не вижу дней",0,690,2,0],["v","Пред собою я",0,691,2,0],["v","Без горючих слез,",0,692,2,0],["v","Без стенаний жалких!",0,693,2,0],["sp","Корифей"],["v","Да, что за ужас, что за ужас это!",0,694,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Дитя, о матери дитя несчастной,",0,695,0,0],["v","Как умер ты? Каким ударом",0,695,2,0],["v","К земле прибит и чья",0,696,2,0],["v","Рука с тобой покончила?",0,697,2,0],["sp","Служанка"],["v","Узнаешь ли? Не берег же расскажет.",0,698,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Волна ли его иль копье",0,699,0,0],["v","Глади песчаной отдали?",0,700,0,1],["sp","Служанка"],["v","Он вынесен прибоем моря бурным.",0,700,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Увы, о, горе… о, сон…",0,701,0,0],["v","Я сон узнала свой!",0,702,0,0],["v","Тот сон чернокрылый,",0,703,0,0],["v","Что видела я.",0,704,0,0],["v","Тебя, знать, вещал он,",0,705,0,0],["v","Вещал, что ушел ты",0,706,0,0],["v","От божьего света",0,707,0,0],["v","В обитель теней.",0,708,0,0],["sp","Корифей"],["v","Но кто ж убил его? Тебе не снилось?",0,709,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Мой гость, мой друг, фракийский конелюбец,",0,710,0,1],["v","Которому отец малютку вверил!",0,711,0,0],["sp","Корифей"],["v","Что говоришь? На золото польстясь?",0,712,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Без имени поступок, наважденье…",0,713,0,0],["v","О, боги милые! Где ж это совесть?",0,714,0,0],["v","Кто за гостя накажет тебя?<a class=\"nr\" href=\"#n-k23\" data-n=\"k23\" aria-label=\"Примечание 23\">23</a>",0,715,0,0],["v","О, будь ты проклят!",0,716,0,0],["v","Так искромсать железом",0,717,0,0],["v","Тело ребенка…",0,720,0,1],["v","Музыка умолкает.",0,720,0,0],["sp","Корифей"],["v","Поистине тебя многострадальной",0,721,0,0],["v","Твой тяжкий демон сделал. Но глаза",0,722,0,0],["v","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнона</span> различают. Тише!",0,723,0,0],["v","Завесу на уста, подруги… Царь.",0,724,0,0],["scene","Явление десятое","s13",4,13],["v","Входит <span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>.",0,725,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Ты не спешишь, однако, с погребеньем.",0,726,0,0],["v","Со слов Талфибия я приказал,",0,727,0,0],["v","Чтобы никто до мертвой не касался…",0,728,0,0],["v","Что ж вышло? Мы отстали, а тебе",0,729,0,0],["v","Все недосуг. Тебя поторопить",0,730,0,1],["v","Я прихожу… А с нашей стороны",0,730,0,0],["v","Все сделано, и хорошо, поверь,",0,731,0,0],["v","Коль может быть хорошим это горе…",0,732,0,0],["sd","(Глядя на труп.)"],["v","Что вижу я? Перед шатром троянец",0,733,0,0],["v","Убитый, да: не греческий покров",0,734,0,0],["v","Его младое тело обвивает…",0,735,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["dir","про себя"],["v","Несчастная, — себе я говорю, —",0,735,0,0],["v","Что сделаешь, Гекуба? Мне колени",0,736,0,0],["v","Его обнять или крепиться молча?",0,737,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Зачем же отвернулась и, склоняясь,",0,738,0,0],["v","Ты слезы льешь, не говоря ни слова?",0,739,0,0],["v","Что вышло здесь? Чье тело пред тобой?",0,740,0,1],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["dir","про себя"],["v","А если он рабыню и врага",0,740,0,0],["v","Во мне лишь видит и от ног отринет",0,741,0,0],["v","Молящую, нам скорби прибавляя?..",0,742,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Не вещим я рожден, чтоб разгадать",0,743,0,0],["v","Твоих дорогу мыслей без ответа…",0,744,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["dir","про себя"],["v","Иль, может быть, напрасно я врагом",0,745,0,0],["v","Его считаю, он же добр и ласков?",0,746,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Коль говорить не хочешь ты, с тобой",0,747,0,0],["v","Мы сходимся — мои закрыты уши…",0,748,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["dir","про себя"],["v","Иль без него смогу я отомстить",0,749,0,0],["v","За сына смерть?.. Мои кружатся мысли…",0,750,0,1],["v","И для чего? Смелее! Будет толк",0,750,0,0],["v","Или не будет — попытаться надо.",0,751,0,0],["sd","(Обращаясь к царю.)"],["v","Агамемнон, молю тебя, колен,",0,752,0,0],["v","И бороды, и гордой от побед",0,753,0,0],["v","Твоей десницы, царь, касаясь нежно…",0,754,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","О чем, жена, ты молишь? Может быть,",0,755,0,0],["v","Освободить тебя? Нетрудно это…",0,755,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","О нет… лишь дай злодея наказать,",0,756,0,0],["v","И кончить век рабыней сладко будет!",0,757,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["dir","грозно сверкнув глазами на <span class=\"ch\" data-ch=\"gekuba\">Гекубу</span>"],["v","И помощи ты просишь у меня?",0,758,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["dir","смиренно"],["v","Не угадал ты, царь, моей кручины.",0,759,0,0],["v","Ты видишь этот труп? Ты видишь слезы?",0,760,0,1],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Я вижу, да; но смысла не постиг.",0,761,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Под поясом носила я его.",0,762,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Он из детей твоих, жена несчастья?",0,763,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","О, не из тех, что пали там, под Троей.",0,764,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","А разве ты еще детей имела?",0,765,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Вот этого, — но не на радость, нет!",0,766,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Но где ж он был, пока ваш брался город?",0,767,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Отец услал его, сберечь хотел…",0,768,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","И отделил от прочих… Но куда ж?",0,769,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","В страну, где мы убитого нашли.",0,770,0,1],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","К царю земли, чье имя <span class=\"ch\" data-ch=\"polimestor\">Полиместор</span>?",0,771,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Да, стражем злата горького, увы!",0,772,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Но кто ж убил его? Как вышло это?",0,773,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Да кто ж другой? Фракийский друг убил.",0,774,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Несчастная… Позарился на деньги?",0,775,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Несчастие фригийское узнав.",0,776,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Где ж вы нашли его и кто принес?",0,777,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Рабыня, царь, вот там — на прибережье.",0,778,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Его ища иль за другим трудом?",0,779,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Шла за водой она — для омовенья.",0,780,0,1],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Царь, видно, выбросил его туда…",0,780,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","На жертву волнам, так изрезав тело!",0,781,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Твоя безмерна мука, это ужас!",0,782,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Все унесу в могилу муки, все.",0,783,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Увы, меж жен кто так же обездолен?",0,784,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Нет никого — опричь самой Недоли!",0,785,0,0],["v","Но выслушай мольбу, с которой жадно",0,785,0,0],["v","К тебе я припадаю. Если скажешь,",0,786,0,0],["v","Что я терплю за дело, — примирюсь",0,787,0,0],["v","И я с своим страданьем. Если ж даром —",0,788,0,0],["v","Ты отомстишь, не правда ль, за меня?",0,789,0,0],["v","Безбожника, не правда ль, покараешь,",0,790,0,1],["v","Забывшего, что боги и под нами,",0,790,0,0],["v","И в небесах живут? А сколько раз",0,791,0,0],["v","Он трапезу делил со мной, считаясь",0,792,0,0],["v","Меж первыми друзьями; все, что долг",0,793,0,0],["v","Велит давать друзьям, — ему давали.",0,794,0,0],["v","А заплатил он чем же? Взяв к себе",0,795,0,0],["v","Ребенка, чтоб спасти его, — убил;",0,796,0,0],["v","Убив, не удостоил и могилы,",0,797,0,0],["v","Нет, в море труп он выбросил. Рабой",0,798,0,0],["v","Бессильной стала я; но есть же боги",0,799,0,0],["v","И тот Закон, что властвует над ними:",0,800,0,1],["v","Ведь по закону верим мы в богов",0,800,0,0],["v","И правду от неправды различаем.",0,801,0,0],["v","И если тот закон тебе вручен,",0,802,0,0],["v","И будет он нарушен, и убийцы",0,802,0,0],["v","Своих гостей иль тати храмовые",0,803,0,0],["v","Не понесут возмездья — сгинет правда",0,804,0,0],["v","Среди людей навеки!.. Но надеюсь,",0,805,0,0],["v","Что оценил его деянья ты!<a class=\"nr\" href=\"#n-k24\" data-n=\"k24\" aria-label=\"Примечание 24\">24</a>",0,805,0,0],["v","Почти ж меня и сжалься; как художник,",0,806,0,0],["v","Шаг отступив, взгляни ты на меня:",0,807,0,0],["v","Все бедствия откроются тебе.",0,807,0,0],["v","Царицею была я — ныне стала",0,808,0,0],["v","Твоей рабой; я матерью была",0,809,0,0],["v","Благословенной — и бездетна ныне",0,810,0,1],["v","На склоне лет; отчизны лишена,",0,810,0,0],["v","Одна на свете, всех несчастней смертных…",0,811,0,0],["sd","Пауза. <span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span> видимо тронут словами <span class=\"ch\" data-ch=\"gekuba\">Гекубы</span>. Она с мучительным напряжением ждет ответа, но он, после некоторого раздумья, качает головой и собирается уйти."],["v","Увы! Увы! Уходишь ты, меня",0,812,0,0],["v","Ты избегаешь, кажется. Усилья",0,813,0,0],["v","Бесплодные!.. О, горькая!.. Зачем,",0,813,0,0],["v","О смертные, мы всем другим наукам",0,814,0,0],["v","Стараемся учиться так усердно,",0,815,0,0],["v","А речь, единую царицу мира,",0,816,0,0],["v","Мы забываем? Вот кому служить",0,816,0,0],["v","Должны бы все, за плату дорогую",0,817,0,0],["v","Учителей сводя, чтоб, тайну слова",0,818,0,0],["v","Познавши, убеждая — побеждать!",0,819,0,0],["v","Не для меня наука эта: в чем же",0,820,0,1],["v","Моя надежда? Сыновей когда-то",0,820,0,0],["v","Имела я — уж нет их. Я копья",0,821,0,0],["v","Несчастная добыча и влачусь,",0,822,0,0],["v","Издалека взирая, как бежит",0,822,0,0],["v","Клубами дым с развалин Трои…",0,823,0,0],["sd","(После отчаянного усилия над собой приближается к <span class=\"ch\" data-ch=\"agamemnon\">Агамемнону</span> и вполголоса говорит ему.)"],["v","Слушай…",0,824,4,0],["v","Хоть, может быть, и попусту любви",0,825,0,0],["v","Придется мне привлечь сюда богиню…",0,825,0,0],["v","У бока твоего ночами спит",0,826,0,0],["v","Та жрица Феба, что зовут Кассандрой",0,827,0,0],["v","Во Фригии. Не забывай же неги",0,827,0,0],["v","Ночей любовных и лобзаний сладких",0,828,0,0],["v","На общем ложе; пусть за них награду",0,829,0,0],["v","Получит дочь моя — и я за дочь.",0,830,0,1],["v","Ведь нет для смертных уз теснее, нет",0,830,0,0],["v","Сильнее чар, чем дань любви во мраке.",0,831,0,0],["v","О, слушай же! Ты видишь этот труп?",0,832,0,0],["v","Ведь это брат Кассандры… Не чужому",0,833,0,0],["v","Поможешь ты…",0,833,0,0],["v","Я кончила… Одно",1,833,0,0],["v","Скажу еще. О, если б чудом голос",0,834,0,0],["v","Открылся у меня теперь в руках",0,835,0,0],["v","И на плечах, и ноги и ступни",0,836,0,0],["v","Когда б теперь мои заговорили",0,836,0,0],["v","Дедаловым искусством иль другим<a class=\"nr\" href=\"#n-k25\" data-n=\"k25\" aria-label=\"Примечание 25\">25</a>",0,837,0,0],["v","Каким-нибудь… Каких бы слов они",0,838,0,0],["v","Тебе ни насказали, с воплем жалким",0,839,0,0],["v","Мешая речь, обняв твои колени:",0,840,0,1],["v","О царь, о солнце дивное Эллады,",0,840,0,0],["v","Дай убедить тебя и протяни",0,841,0,0],["v","Старухе руку помощи… Пускай",0,842,0,0],["v","Она ничто, но ты велик, ты славен…",0,843,0,0],["v","Кто доблестен, в том правда и оплот:",0,844,0,0],["v","Где б ни увидел злых, он их карает!",0,845,0,0],["sp","Корифей"],["v","Как странно нас судьба мутит порой.",0,846,0,0],["v","И новый долг над старым торжествует",0,847,0,0],["v","Сознаньем крови, то являя другом",0,848,0,0],["v","Врага, то друга делая врагом.",0,849,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Гекуба, жаль тебя мне, и ребенка",0,850,0,1],["v","Жалею я; хотел бы я почтить",0,850,0,0],["v","Молящую десницу; бога ради",0,851,0,0],["v","И вечной Правды я б желал, чтоб изверг",0,852,0,0],["v","Возмездье принял от тебя. Хочу",0,853,0,0],["v","Лишь одного: чтоб, дав тебе отраду,",0,854,0,0],["v","Не встретил я упрека, что воздал",0,855,0,0],["v","Я за любовь Кассандре кровью гостя",0,855,0,0],["v","Фракийского… Вот этой мыслью я",0,856,0,0],["v","Смущен, жена. Его считает войско",0,857,0,0],["v","Союзником, а мертвого — врагом.",0,858,0,0],["v","Пусть мне он лично близок, но не может",0,859,0,0],["v","Дружинам быть таким же он. Возьми ж",0,860,0,1],["v","Все это в толк… Помочь я рад, ты видишь,",0,860,0,0],["v","И хоть сейчас, да оторопь берет —",0,861,0,0],["v","Ахеец бы за это не расславил.",0,862,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Увы! Увы!",0,863,1,0],["v","Свободы нет меж смертными: один",0,863,0,0],["v","Богатства раб, а тот — судьбы, иному",0,864,0,0],["v","Кладет предел толпа его сограждан,",0,865,0,0],["v","Тем письмена законов не велят",0,866,0,0],["v","Так поступать, как хочет их природа.",0,866,0,0],["v","Ну что ж, и ты не исключенье: черни",0,867,0,0],["v","Боится царь. Раба освободит",0,868,0,0],["v","Его от страха этого. Ты будешь",0,869,0,0],["v","Поверенным моей коварной мести,",0,870,0,1],["v","Помощником не будешь. Лишь тогда,",0,870,0,0],["v","Когда б ахейцы подняли тревогу",0,871,0,0],["v","И двинулись фракийца выручать",0,872,0,0],["v","От кары, им заслуженной, — своих",0,873,0,0],["v","Попридержи солдат, не подавая",0,873,0,0],["v","И вида, что в угоду мне. А там",0,874,0,0],["v","Я все сама устрою, будь спокоен.",0,875,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Что именно устроишь ты и как",0,876,0,0],["v","С мечом пойдешь на варвара в дрожащей",0,876,0,0],["v","Руке, жена? Отравишь? На кого ж",0,877,0,0],["v","Надеешься? Кто ополчится вместе",0,878,0,0],["v","С тобой и где друзей тебе добыть?",0,879,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Троянок мало ль эти сени кроют?",0,880,0,1],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Про пленниц ты ахейских говоришь?",0,880,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","С их помощью я заплачу убийце.",0,881,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Где же мужчин вам, женам, одолеть?",0,882,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Нас много, хитрость же удвоит силы.",0,883,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Подумаешь!.. Весь род ничтожен ваш.",0,884,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Что так? Детей Египтовых не жены ль",0,885,0,0],["v","Осилили, а Лемнос от мужчин<a class=\"nr\" href=\"#n-k26\" data-n=\"k26\" aria-label=\"Примечание 26\">26</a>",0,886,0,0],["v","Не женщины очистили, ты скажешь?",0,887,0,0],["v","Но будь что будет… Кончим разговор;",0,888,0,0],["v","Ты женщине вот этой через лагерь",0,889,0,0],["v","Дай пропуск, Агамемнон…",0,890,0,1],["sd","(Служанке.)"],["v","Ты ж, жена,",0,890,4,0],["v","Приблизишься к фракийцу со словами,",0,891,0,0],["v","Что бывшая царица Трои просит",0,891,0,0],["v","Его прийти с детьми, что дело, мол,",0,892,0,0],["v","Есть общее и не мешает слышать",0,892,0,0],["v","О нем и детям гостя.",0,893,0,0],["v","Служанка уходит.",0,894,0,0],["v","Задержи",0,894,4,0],["v","Дочернее, коль можешь, погребенье,",0,895,0,0],["v","Агамемнон, чтоб с братом вместе их",0,895,0,0],["v","Похоронить могла я в землю; это",0,896,0,0],["v","Двойное горе матери пускай",0,897,0,0],["v","Один костер сожжет, испепеляя.",0,897,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Пусть так оно и будет. Все равно",0,898,0,0],["v","Наш путь закрыт покуда, и моей",0,898,0,0],["v","Нет милости преграды. Ветра, видишь,",0,899,0,0],["v","Нам не дал бог, — и в ожиданье мы",0,900,0,1],["v","На тихое глядим тревожно море.",0,900,0,0],["v","Ну, в добрый час! Для нас и городов —",0,901,0,0],["v","Прямая польза, если остаются",0,902,0,0],["v","Счастливыми достойные, а те,",0,903,0,0],["v","Кто зло творил, свою приемлют кару.",0,904,0,0],["sd","(Уходит.)"],["scene","Третий музыкальный антракт","s14",4,14],["sp","Хор"],["str","Строфа I"],["v","Ты, Илион, наша отчизна —",0,905,0,0],["v","Больше тебя средь городов",0,906,0,0],["v","Несокрушимых не назовут…",0,907,0,0],["v","Облака тяжкие кроют тебя,",0,908,0,0],["v","Эллинов ярые копья…",0,909,0,0],["v","Сбриты твои башни — пятно",0,910,0,1],["v","В копоти ярко горит,",0,910,0,0],["v","Плача достойное… Я же,",0,911,0,0],["v","Горькая, больше в твои",0,912,0,0],["v","Стены уже не вступлю…",0,913,0,0],["str","Антистрофа I"],["v","В полночь меня гибель застигла.",0,914,0,0],["v","Ужели прошел сладостный сон?",0,915,0,0],["v","Очи смежая, мир погасил",0,916,0,0],["v","Звуки и жертвы радость унес.",0,917,0,0],["v","Спальня уж мужа сманила,",0,918,0,0],["v","Там до утра он копье",0,919,0,0],["v","Сонный повесил на крюк;",0,920,0,1],["v","Он уж увидеть не мог,",0,920,0,0],["v","Как мореходов толпа",0,921,0,0],["v","В древний вошла Илион…",0,922,0,0],["str","Строфа II"],["v","Я же локоны на ночь густые",0,923,0,0],["v","Убирала под митру; глаза",0,924,0,0],["v","В золоченое зеркало долго",0,925,0,0],["v","Уходили лучами, слипаясь;",0,925,0,0],["v","Наконец я на ложе склонилась…",0,926,0,0],["v","А по городу клики неслися",0,927,0,0],["v","И, призывные, Трою будили:",0,928,0,0],["v","\"О, когда же, когда, сокрушив",0,929,0,0],["v","Илионского кремля твердыню,",0,930,0,1],["v","К очагам вы воротитесь, греки?",0,931,0,0],["v","Скоро ль, скоро ль, дети ахейцев?\"",0,932,0,0],["str","Антистрофа II"],["v","Я покинула милое ложе",0,933,0,0],["v","И, одеждой прикрыта едва,",0,934,0,0],["v","Как спартанская дева, небрежно",0,935,0,0],["v","Я к Латониной дщери припала,",0,936,0,0],["v","Но склонить не могла Артемиды.",0,937,0,0],["v","Муж убит у меня на глазах,",0,938,0,0],["v","А меня увлекают к другому",0,939,0,0],["v","По родимым волнам, и ладья",0,940,0,1],["v","Уж обратно стремится, курган",0,940,0,0],["v","От очей моих город скрывает,",0,941,0,0],["v","И от скорби я, горькая, таю!..",0,942,0,0],["str","Эпод"],["v","Елену, сестру Диоскуров",0,943,0,0],["v","И горе Париса, влекома,",0,943,0,0],["v","Кляла я… Тот брак злополучный —",0,944,0,0],["v","Не брак, наваждение ада, —",0,945,0,0],["v","Не он ли от отчей земли",0,946,0,0],["v","Меня оторвал и на гибель",0,946,0,0],["v","Отцовский очаг погасил нам!",0,947,0,0],["v","О, будь проклята ты, невеста!",0,948,0,0],["v","Тебя по пучине лазурной",0,949,0,0],["v","Назад да не двинет волна;",0,950,0,1],["v","Тебя да не примет, лаская,",0,950,0,0],["v","С возвратом отцовская сень!",0,951,0,0],["act","Исход","a5",""],["scene","Явление одиннадцатое","s15",5,15],["sd","<span class=\"ch\" data-ch=\"polimestor\">Полиместор</span> в сопровождении сыновей и свиты появляется со стороны суши. Завидев <span class=\"ch\" data-ch=\"gekuba\">Гекубу</span>, он с притворной сердечностью обращается к ней."],["sp","<span class=\"ch\" data-ch=\"polimestor\">Полиместор</span>"],["v","Приам, о лучший друг, и ты, <span class=\"ch\" data-ch=\"gekuba\">Гекуба</span><a class=\"nr\" href=\"#n-k27\" data-n=\"k27\" aria-label=\"Примечание 27\">27</a>",0,952,0,0],["v","Любезная, я плачу над тобой,",0,953,0,0],["v","Над городом погибшим и твоей",0,954,0,0],["v","Царевною, убитою сегодня…",0,955,0,0],["v","Увы! Увы!",0,955,0,0],["v","Чему же доверять? Не славе только…",0,956,0,0],["v","Не прочности удачи тоже, впрочем…",0,957,0,0],["v","Бессмертные, волнуя мир, и наш",0,958,0,0],["v","Волнуют ум, чтоб в ослепленье детском",0,959,0,0],["v","Мы чтили их… Довольно слез, однако:",0,960,0,1],["v","Ведь этим мук на завтра не избудешь!",0,960,0,0],["v","Ты сердишься, быть может, на меня",0,961,0,0],["v","За то, что не пришел. Повремени же:",0,962,0,0],["v","Во Фракии срединной я как раз",0,963,0,0],["v","В то время был, как вас сюда прибило…",0,964,0,0],["v","Едва успел вернуться — собрался",0,965,0,0],["v","Идти к тебе, — рабыня, и с рассказом.",0,966,0,0],["v","Я выслушал ее — и здесь, как видишь…",0,967,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Стыжусь глядеть я прямо на тебя,",0,968,0,0],["v","Фракийский гость, из этой тины бедствий…",0,969,0,0],["v","Кто видел нас счастливыми, тому",0,970,0,1],["v","Нам тяжело явить свои лохмотья…",0,971,0,0],["v","Глаза поднять боимся мы. Враждой",0,972,0,0],["v","Ты не считай же робости, фракиец…",0,973,0,0],["v","Но есть еще одна причина: нрав",0,974,0,0],["v","Нам не велит глядеть в глаза мужчинам.",0,975,0,0],["sp","<span class=\"ch\" data-ch=\"polimestor\">Полиместор</span>"],["v","Мудреного тут нет. Но чем могу",0,976,0,0],["v","Служить тебе? Зачем из дома вызван?",0,977,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Есть личные дела до сыновей",0,978,0,0],["v","Твоих и до тебя; и если можно,",0,979,0,0],["v","То свиту удали, царь <span class=\"ch\" data-ch=\"polimestor\">Полиместор</span>.",0,980,0,1],["sp","<span class=\"ch\" data-ch=\"polimestor\">Полиместор</span>"],["dir","к свите"],["v","Ступайте же. Без страха я один",0,980,0,0],["v","Останусь здесь. С тобою мы друзья,",0,981,0,0],["v","И греческий нам не враждебен лагерь.",0,982,0,0],["v","Свита уходит. <span class=\"ch\" data-ch=\"polimestor\">Полиместор</span> продолжает.",0,983,0,0],["v","Что ж должен дать — открой теперь, Гекуба,",0,984,0,0],["v","Несчастному благополучный друг?",0,985,0,0],["v","В готовности моей не сомневайся.",0,985,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Скажи сперва: что Полидор, мой сын,",0,986,0,0],["v","Отцом и мной тебе врученный? Жив ли?",0,987,0,0],["v","А прочее и подождет пока…",0,988,0,0],["sp","<span class=\"ch\" data-ch=\"polimestor\">Полиместор</span>"],["v","Живехонек… Вам в этом деле счастье…",0,989,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","О милый, вот достойные слова!",0,990,0,1],["sp","<span class=\"ch\" data-ch=\"polimestor\">Полиместор</span>"],["v","Ну, дальше, что хотела ты спросить?",0,991,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Он помнит ли о матери родимой?",0,992,0,0],["sp","<span class=\"ch\" data-ch=\"polimestor\">Полиместор</span>"],["v","Тайком к тебе пробраться он хотел…",0,993,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","И золото троянское ведь цело?",0,994,0,0],["sp","<span class=\"ch\" data-ch=\"polimestor\">Полиместор</span>"],["v","Сохранно и в дому моем лежит.",0,995,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Храни ж его, не пожелай чужого…",0,996,0,0],["sp","<span class=\"ch\" data-ch=\"polimestor\">Полиместор</span>"],["v","Ничуть… Ничуть… Нам будет своего.",0,997,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Тебе и детям речь мою — ты знаешь?",0,998,0,0],["sp","<span class=\"ch\" data-ch=\"polimestor\">Полиместор</span>"],["v","Не знаю, но надеюсь услыхать.",0,999,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","О свет очей моих, есть нечто, милый…",0,1000,0,1],["sp","<span class=\"ch\" data-ch=\"polimestor\">Полиместор</span>"],["v","Что именно, столь важное для нас?",0,1001,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["dir","таинственно"],["v","Есть золото в подвалах Приамидов…",0,1002,0,0],["sp","<span class=\"ch\" data-ch=\"polimestor\">Полиместор</span>"],["v","Для сына весть, не правда ли, твоя?",0,1003,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Через тебя, о честный человек!",0,1004,0,0],["sp","<span class=\"ch\" data-ch=\"polimestor\">Полиместор</span>"],["v","Но сыновья мои-то тут при чем же?",0,1005,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Им нужно знать, коль раньше ты умрешь.",0,1006,0,0],["sp","<span class=\"ch\" data-ch=\"polimestor\">Полиместор</span>"],["v","Да, это так, все надобно предвидеть.",0,1007,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Ты знаешь храм Афины Илионской?<a class=\"nr\" href=\"#n-k28\" data-n=\"k28\" aria-label=\"Примечание 28\">28</a>",0,1008,0,0],["sp","<span class=\"ch\" data-ch=\"polimestor\">Полиместор</span>"],["v","Там золото? Но как узнать мне место?",0,1009,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Есть каменный и черный выступ там.",0,1010,0,1],["sp","<span class=\"ch\" data-ch=\"polimestor\">Полиместор</span>"],["v","О золоте вопрос исчерпан этим?",0,1010,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["dir","еще таинственнее"],["v","Я привезла сокровища с собой,",0,1011,0,0],["v","Их дать тебе хочу на сохраненье.",0,1012,0,0],["sp","<span class=\"ch\" data-ch=\"polimestor\">Полиместор</span>"],["v","Под пеплосом ты затаила их?",0,1013,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Нет, под тряпьем в палатке этой прячу.",0,1014,0,0],["sp","<span class=\"ch\" data-ch=\"polimestor\">Полиместор</span>"],["v","Ахейский флот палатки здесь разбил…",0,1015,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Да, но шатры особые для пленниц.",0,1016,0,0],["sp","<span class=\"ch\" data-ch=\"polimestor\">Полиместор</span>"],["v","Они смолчат? И нет мужчин вблизи?",0,1017,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Ни одного ахейца — только жены.",0,1018,0,0],["v","Войди ж в шатер, и поскорей: аргосцы",0,1019,0,0],["v","Расправить крылья кораблям спешат.",0,1020,0,1],["v","Хочу тебя принять я по заслугам,",0,1020,0,0],["v","Затем — с детьми назад в тот дом отправить,",0,1021,0,0],["v","Где поселил ты сына моего.",0,1022,0,0],["sd","<span class=\"ch\" data-ch=\"polimestor\">Полиместор</span> входит в шатер в сопровождении сыновей. <span class=\"ch\" data-ch=\"gekuba\">Гекуба</span> идет за ними."],["scene","Явление двенадцатое","s16",5,16],["sp","Хор"],["v","Ты не платил пока, но все отдашь…",0,1023,0,0],["v","В море открытом,",0,1024,2,0],["v","Коль человек, падая в воду,",0,1025,2,0],["v","Душу теряет с милой надеждой, —",0,1026,0,0],["v","Твой это брат!",0,1027,2,0],["v","Если зараз платы хотят",0,1028,0,0],["v","Правда и боги,",0,1029,0,0],["v","Смерть, смерть их насытит.",0,1030,2,1],["v","Златообманной стезей",0,1030,0,0],["v","К гибели верной идешь ты;",0,1031,0,0],["v","Горький, бессильной руке",0,1032,0,0],["v","Жизни светило отдашь ты!",0,1033,0,0],["sp","<span class=\"ch\" data-ch=\"polimestor\">Полиместор</span>"],["dir","в глубине шатра"],["v","Ой-ой!",0,1034,2,0],["v","Несчастному, глаза мне вырывают!",0,1035,0,0],["sp","Корифей"],["v","Вы слышите фракийца стон, подруги?",0,1036,0,0],["sp","<span class=\"ch\" data-ch=\"polimestor\">Полиместор</span>"],["v","Детей моих зарезали, детей…",0,1037,0,0],["sp","Корифей"],["dir","у дверей палатки"],["v","В шатре свершилось новое несчастье.",0,1038,0,0],["sp","<span class=\"ch\" data-ch=\"polimestor\">Полиместор</span>"],["v","Нет! Легкие вас ноги не спасут,",0,1039,0,0],["v","Я расшибу шатер до основанья!",0,1040,0,1],["sp","Корифей"],["v","Вот полетел из тяжкой длани камень!",0,1041,0,0],["v","Что ж, бросимся все вместе! Не пора ль",0,1042,0,0],["v","Помочь <span class=\"ch\" data-ch=\"gekuba\">Гекубе</span> и троянкам, сестры?",0,1043,0,0],["scene","Явление тринадцатое","s17",5,17],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["dir","появляясь из шатра"],["v","Ну что ж, срывай ворота, дом ломай!",0,1044,0,0],["v","Но между век ты глаз не вставишь светлых",0,1045,0,0],["v","И сыновей убитых не вернешь!",0,1046,0,0],["sp","Корифей"],["v","Сразила ты фракийца, госпожа?",0,1047,0,0],["v","Свершилось, что слова твои вещают?",0,1048,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Сама сейчас увидишь перед домом",0,1049,0,0],["v","Неверные шаги слепца, детей",0,1050,0,1],["v","Его двоих тела, убитых мною",0,1050,0,0],["v","И цветом жен троянских также. Да,",0,1051,0,0],["v","Он заплатил мне долг. Идет, глядите!",0,1052,0,0],["v","Я отойду немного, чтоб впустую",0,1053,0,0],["v","Поток пронесся злобы необорной.",0,1054,0,0],["scene","Явление четырнадцатое","s18",5,18],["sd","Из палатки выходит ослепленный <span class=\"ch\" data-ch=\"polimestor\">Полиместор</span> с согнутым телом и устремленными вперед руками. Через открытые двери видны трупы его сыновей. Музыка."],["sp","<span class=\"ch\" data-ch=\"polimestor\">Полиместор</span>"],["v","Увы мне!",0,1055,2,0],["v","Куда пойду? Где стану? Где причалю?",0,1055,0,0],["v","Когда бы на след",0,1056,0,0],["v","Напасть их! Но как?",0,1057,0,0],["v","Как горные звери, к ногам",0,1058,2,0],["v","Прибавивши руки?",0,1059,2,0],["v","Где путь мой? Направо? Налево?",0,1060,2,1],["v","Схватить горит мое сердце",0,1060,2,0],["v","Троянок, меня погубивших,",0,1061,2,0],["v","Обрызганных кровью моей!..",0,1062,2,0],["v","О жалкие дочери Трои,",0,1063,2,0],["v","Проклятье на вас!",0,1064,2,0],["v","Куда вы забились? О, Солнце,",0,1065,2,0],["v","Мои кровавые веки,",0,1066,2,0],["v","Бог, исцели слепые,",0,1067,2,0],["v","Лучом поделись со мной…",0,1068,2,0],["v","О!.. О!..",0,1069,2,0],["v","Тише… Чудится шаг затаенный…",0,1070,2,1],["v","Это они… Ринусь туда!..",0,1070,2,0],["v","Кости и мясо пожру их…",0,1071,2,0],["v","Сделаюсь зверем, позор",0,1072,2,0],["v","Им отплачу сторицей!..",0,1073,2,0],["sd","(Хочет броситься по направлению к хору, затем спохватывается и отступает, ища палатки.)"],["v","О, я, несчастный… Куда ж,",0,1074,2,0],["v","Куда я иду? А дети?",0,1075,2,0],["v","Ведь адские эти менады",0,1075,2,0],["v","Тела их растреплют…",0,1076,2,0],["v","В снедь обратят сворам собак,",0,1077,2,0],["v","В красный и дикий обед,",0,1078,2,0],["v","В горную падаль…",0,1079,2,0],["v","Куда ж мне идти? Где стану? Колени",0,1080,2,1],["v","Согну, опускаясь, куда?",0,1080,2,0],["v","Я, как мореход, свой парус холщовый",0,1081,2,0],["v","Спущу на канатах… довольно…",0,1082,2,0],["v","На ложе я сторожем пряну,",0,1083,2,0],["v","На ложе, увы!",0,1083,2,0],["v","Могильного сна сыновей.",0,1084,2,0],["sd","(Продолжает искать палатки.)"],["sp","Корифей"],["v","О горький муж!.. Невыносимы муки",0,1085,0,0],["v","Твои, но кару эту заслужил",0,1086,0,0],["v","Деянием позорным ты у бога…",0,1086,0,0],["sp","<span class=\"ch\" data-ch=\"polimestor\">Полиместор</span>"],["v","Ой… муки… Ой…",0,1087,0,0],["v","Фракийцы, ты, народ мой, на конях…",0,1088,0,0],["v","В оружии, копейщик…",0,1089,0,0],["v","О род, о род, Аресом одержимый,",0,1090,0,1],["v","Ахейцы… Вы, Атриды,",0,1090,0,0],["v","Сюда… сюда… сюда…",0,1091,0,0],["v","Богами вас заклинаю я…",0,1092,0,0],["v","О, поскорей сюда!..",0,1093,0,0],["v","Слышите ль? Иль никто",0,1094,0,0],["v","Мне не поможет? Зачем",0,1095,0,0],["v","Медлите вы?..",0,1095,0,0],["v","Жены убили меня,",0,1096,0,0],["v","Пленницы ваши…",0,1097,0,0],["v","Вынес я ужас, о, ужас!..",0,1098,0,0],["v","О, боги, какое мученье!..",0,1099,0,0],["v","О, где же мой путь? О, где мой приют?",0,1100,0,1],["v","О, если бы в высь небес,",0,1101,0,0],["v","В этот горний чертог нам;",0,1102,0,0],["v","Там Орион, Сириус там",0,1103,0,0],["v","В ярких огнистых лучах!..",0,1104,0,0],["v","Или меня черный Аид",0,1105,0,0],["v","В пропасти трупом поднимет?",0,1106,0,0],["sp","Корифей"],["v","Простительно, коль муки выше сил,",0,1107,0,0],["v","Желать уйти из этой жалкой жизни.",0,1108,0,0],["scene","Явление пятнадцатое","s19",5,19],["sd","<span class=\"ch\" data-ch=\"polimestor\">Полиместор</span> продолжает беспомощно метаться, <span class=\"ch\" data-ch=\"gekuba\">Гекуба</span> стоит в стороне, не спуская с него глаз. Со стороны стана приходит <span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span> с телохранителями."],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Я прихожу на крики. Дева, дочь",0,1109,0,0],["v","Скалистого утеса, не осталась<a class=\"nr\" href=\"#n-k29\" data-n=\"k29\" aria-label=\"Примечание 29\">29</a>",0,1110,0,1],["v","Спокойною и, повторивши крик,",0,1110,0,0],["v","Весь лагерь наш исполнила смятеньем…",0,1111,0,0],["v","Когда б не знали мы, что под копьем",0,1112,0,0],["v","Ахейским пала Троя, страх немалый",0,1112,0,0],["v","Нагнал бы этот дикий вопль на нас.",0,1113,0,0],["sp","<span class=\"ch\" data-ch=\"polimestor\">Полиместор</span>"],["v","О друг, тебя по голосу узнал я…",0,1114,0,0],["v","Ты видишь, что со мною, Агамемнон?",0,1115,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["dir","с притворным удивлением"],["v","Ба!..",0,1115,1,0],["v","Несчастный <span class=\"ch\" data-ch=\"polimestor\">Полиместор</span>, кто сгубил",0,1116,0,0],["v","Тебя и веки кровью запечатал?",0,1117,0,0],["sd","(Бросив взор в палатку, двери которой остаются открытыми.)"],["v","И кто детей убил твоих? Уж, верно,",0,1117,0,0],["v","Тот человек питал великий гнев,",0,1118,0,0],["v","Кто б ни был он, на вас на всех, фракиец…",0,1119,0,0],["sp","<span class=\"ch\" data-ch=\"polimestor\">Полиместор</span>"],["v","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span> нас и пленницы, Атрид,",0,1120,0,1],["v","Сгубили… нет!.. нет, больше чем сгубили!..",0,1120,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Что говоришь?.. Он говорит, Гекуба,",0,1121,0,0],["v","О дерзости твоей, твоем безумье?..",0,1122,0,0],["sp","<span class=\"ch\" data-ch=\"polimestor\">Полиместор</span>"],["v","Увы! Что слышу я?.. Где?.. Где ж она?..",0,1123,0,0],["v","Скажи яснее, чтоб, схватив руками,",0,1124,0,0],["v","Я изорвал, искровенил ее!..",0,1125,0,0],["sd","(Опять начинает метаться.)"],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["dir","строго"],["v","Эй… что с тобой?..",0,1126,0,0],["sp","<span class=\"ch\" data-ch=\"polimestor\">Полиместор</span>"],["v","Богами умоляю,",1,1126,0,0],["v","Дай яростной руке ее моей…",0,1127,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Поудержись. И, удалив из сердца",0,1128,0,0],["v","Свирепое желанье, говори,",0,1129,0,0],["v","Чтоб, выслушав обоих вас, сказать",0,1130,0,1],["v","По совести я мог, за что ты терпишь…",0,1130,0,0],["sp","<span class=\"ch\" data-ch=\"polimestor\">Полиместор</span>"],["v","Я все скажу. Последний Приамид",0,1131,0,0],["v","Был Полидор, <span class=\"ch\" data-ch=\"gekuba\">Гекубою</span> рожденный…",0,1132,0,0],["v","Его Приам-отец мне поручил",0,1133,0,0],["v","Воспитывать в моем старинном доме…",0,1134,0,0],["v","Боялся он за Трою. Полидора",0,1135,0,0],["v","Я умертвил, — ты выслушай, за что,",0,1135,0,0],["v","И ты поймешь, что хорошо я сделал,",0,1136,0,0],["v","Расчетливо. Я не хотел врага",0,1137,0,0],["v","Ахейского хранить, чтобы собрал он",0,1138,0,0],["v","И вновь застроил Трою. Ведь узнай",0,1139,0,0],["v","Ахейцы о Приамовом отродье, —",0,1140,0,1],["v","Они б опять на Трою поднялись,",0,1140,0,0],["v","И наши бы страдали нивы снова",0,1141,0,0],["v","От грабежей; ее сосед бы снова",0,1142,0,0],["v","Тогда терпел, что было нашей долей,",0,1143,0,0],["v","О царь Атрид…",0,1143,0,0],["v","О жребии узнав",1,1143,0,0],["v","Убийственном отродья, заманила",0,1144,0,0],["v","Меня сюда <span class=\"ch\" data-ch=\"gekuba\">Гекуба</span> обещаньем",0,1145,0,0],["v","Клад золотой Приамовых детей",0,1146,0,0],["v","Открыть и, где лежит он, обозначить;",0,1146,0,0],["v","И одного, с детьми лишь, в свой шатер",0,1147,0,0],["v","Она ведет меня, чтоб тайной было,",0,1148,0,0],["v","Что будет говорить. Уселся я,",0,1149,0,0],["v","Колени подогнув, на ложе. Было",0,1150,0,1],["v","Немало там троянок молодых, —",0,1150,0,0],["v","Они сидели возле: кто направо,",0,1151,0,0],["v","Кто слева был, по-дружески, Атрид;",0,1152,0,0],["v","Кто пеплос мой на свет глядел и тканью<a class=\"nr\" href=\"#n-k31\" data-n=\"k31\" aria-label=\"Примечание 31\">31</a>",0,1153,0,0],["v","Эдонской любовался, а другие",0,1154,0,0],["v","Дивились на оружье, и мои",0,1155,0,0],["v","Два дротика фракийских по рукам",0,1155,0,0],["v","У них пошли. А матери малюток",0,1156,0,0],["v","Хвалили громко, на руках качали,",0,1157,0,0],["v","Одна другой передавали их,",0,1158,0,0],["v","Чтоб от отца подальше их убрать.",0,1159,0,0],["v","И вдруг, средь самых ласковых речей —",0,1160,0,1],["v","Сверкает из-под платья меч — и гибнут",0,1160,0,0],["v","В мгновенье ока сыновья мои;",0,1161,0,0],["v","Другие в это время на меня",0,1162,0,0],["v","Со злобою: кто за ноги хватает,",0,1163,0,0],["v","Кто за руки… Я к детям… Но лицо",0,1164,0,0],["v","Чуть подниму, мне в волосы вцеплялись;",0,1165,0,0],["v","Чуть шевельну руками, целый рой",0,1166,0,0],["v","Навалится, и, горький, я без силы…",0,1167,0,0],["v","И наконец, последняя беда,",0,1168,0,0],["v","И самое ужасное их дело:",0,1169,0,0],["v","Они мои злосчастные зрачки",0,1170,0,1],["v","Булавкою проткнули и из впадин",0,1170,0,0],["v","Их вырвали кровавым острием…",0,1171,0,0],["v","Потом по дому брызнули. Я прянул",0,1172,0,0],["v","И бросился на кровожадных псиц;",0,1172,0,0],["v","По всем углам за ними рыщу даром,",0,1173,0,0],["v","Охотнику подобен, — все мечу,",0,1174,0,0],["v","Ломаю все, что на пути.",0,1175,0,0],["v","Так вот что",1,1175,0,0],["v","Я вытерпел, Агамемнон, тебе",0,1175,0,0],["v","Желая угодить того убийством,",0,1176,0,0],["v","Кто был врагом тебе. Я не хочу",0,1177,0,0],["v","Излишних слов, Атрид; но все, что раньше",0,1177,0,0],["v","Кто молвил против женщин, ныне молвит",0,1178,0,0],["v","Иль будет молвить впредь — я все в одном",0,1179,0,0],["v","Сосредоточу слове: нет ни в море,",0,1180,0,1],["v","Ни на земле такой напасти лютой;",0,1180,0,0],["v","Кто их познал, тот знает, что я прав.",0,1181,0,0],["sp","Корифей"],["v","Умерь свой пыл, и собственных обид<a class=\"nr\" href=\"#n-k30\" data-n=\"k30\" aria-label=\"Примечание 30\">30</a>",0,1182,0,0],["v","Не вымещай на всей породе нашей.",0,1183,0,0],["v","Меж женщин есть порочные; но мы,",0,1184,0,0],["v","Другие, на весах ведь тоже тянем.",0,1185,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Агамемн<em>о</em>н, не надо бы словам",0,1186,0,0],["v","Сильнее быть поступков. Если дело",0,1187,0,0],["v","Кто совершил благое, пусть и речь",0,1188,0,0],["v","Его звучит приятно; если ж дурно",0,1189,0,0],["v","Он поступил — пусть зло сквозит и в речи,",0,1190,0,1],["v","И не рядится в праздничный наряд",0,1190,0,0],["v","Неправда. О, до тонкости дошли",0,1191,0,0],["v","В искусстве льстивом умники; но все же",0,1192,0,0],["v","И ум им изменяет, покидая",0,1193,0,0],["v","Искусников. Не ускользнет никто!",0,1194,0,0],["v","К тебе начало это, Агамемнон!",0,1195,0,0],["v","Теперь тому отвечу в свой черед…",0,1195,0,0],["v","Ты говорил, что иначе ахейцам",0,1196,0,0],["v","Еще войну вести пришлось бы… Мой",0,1197,0,0],["v","Убит-де сын <span class=\"ch\" data-ch=\"agamemnon\">Агамемнона</span> ради…",0,1198,0,0],["v","Но, жалкий между жалких, разве варвар<a class=\"nr\" href=\"#n-k32\" data-n=\"k32\" aria-label=\"Примечание 32\">32</a>",0,1199,0,0],["v","Когда-нибудь для грека будет друг?",0,1200,0,1],["v","Ведь это невозможно. Что же крылья",0,1200,0,0],["v","Расправило тебе? Иль, может быть,",0,1201,0,0],["v","О сватовстве мечтал ты, иль родню",0,1202,0,0],["v","Оберегал, иль что же, наконец?",0,1202,0,0],["v","Они должны, мол, были, вновь приплыв,",0,1203,0,0],["v","Фракийские попортить насажденья…",0,1204,0,0],["v","Но убедить кого же этим ты",0,1205,0,0],["v","Рассчитывал, скажи!",0,1205,0,0],["v","Когда бы правду",1,1205,0,0],["v","Ты высказать решился… Вот она:",0,1206,0,0],["v","Убили сына — золото и жадность!",0,1207,0,0],["v","Не то — ответствуй мне: пока блистал",0,1207,0,0],["v","Наш Илион, и город охраняла",0,1208,0,0],["v","Ограда стен старинных, и пока",0,1209,0,0],["v","Был жив Приам, и Гектора победой",0,1210,0,1],["v","Еще копье венчалось, — что ж тогда,",0,1210,0,0],["v","Коль ты горел любовию к Атридам,",0,1211,0,0],["v","Не вспомнил ты, что враг их Полидор —",0,1212,0,0],["v","Питомец твой, и не убил ребенка",0,1212,0,0],["v","Или живым не отдал греку? О,",0,1213,0,0],["v","Ты ждал, и вот, когда под солнцем места",0,1214,0,0],["v","Нам больше нет, когда один лишь дым",0,1214,0,0],["v","От вражьего пожара возвещает,",0,1215,0,0],["v","Что город здесь стоял, — тогда убил",0,1216,0,0],["v","У очага ты гостя!..",0,1216,0,0],["v","Слушай дальше,",1,1216,0,0],["v","Чем низок ты: тебе бы надо было,",0,1217,0,0],["v","Раз в дружбе ты с ахейцами, отдать",0,1218,0,0],["v","Им золото — ведь сам же ты признался,",0,1218,0,0],["v","Что не твое оно, а Полидора.",0,1219,0,0],["v","Друзья ж твои нуждались и давно уж",0,1220,0,1],["v","Отделены от родины… А ты",0,1220,0,0],["v","И до сих пор из рук не выпускаешь",0,1221,0,0],["v","Своих мешков, их думая в дому",0,1222,0,0],["v","Попридержать. Да, если б продолжал",0,1223,0,0],["v","Ты моего питать ребенка, долгу",0,1224,0,0],["v","Покорный своему, ты б сохранил",0,1225,0,0],["v","И славу добрую! Ведь в бедах дружба",0,1226,0,0],["v","Пытается… Кто счастию не друг?",0,1227,0,0],["v","Нужда тебя пристигни — в Полидоре",0,1228,0,0],["v","Нашел бы помощь верную всегда ты…",0,1229,0,0],["v","А то теперь ни ты царю не друг,",0,1230,0,1],["v","Ни золото не в радость, ни потомство…",0,1230,0,0],["v","И весь ты тут!..",0,1231,0,0],["v","Тебе, Агамемнон,",1,1231,0,0],["v","Еще скажу: коль ты ему поможешь,",0,1232,0,0],["v","Себя ты опозоришь; в этом госте",0,1233,0,0],["v","Нельзя почтить ни набожность, ни честь,",0,1234,0,0],["v","Ни правду, ни законность… Скажут даже,",0,1235,0,0],["v","Что низким рад ты, потому что сам…",0,1236,0,0],["v","Но поносить господ раба не смеет.",0,1237,0,0],["sp","Корифей"],["v","Кто в деле прав, тому и речь благую",0,1238,0,0],["v","Внушит сознанье правоты своей.",0,1239,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Чужих грехов судьею быть меня",0,1240,0,1],["v","Не радует нисколько. А придется…",0,1240,0,0],["v","За дело взявшись, бросить дело — стыд.",0,1241,0,0],["v","По-моему, чтобы ты знал, ты гостя",0,1242,0,0],["v","Убил совсем не мне в угоду: мы,",0,1243,0,0],["v","Ахейцы, ни при чем: присвоить злато",0,1244,0,0],["v","Хотел ты и, пристигнутый бедой,",0,1245,0,0],["v","Полезных слов себе ты ищешь. Гостя",0,1246,0,0],["v","Убить у вас, быть может, и пустяк,",0,1247,0,0],["v","Ну, а для нас, для эллинов, — постыдно!",0,1248,0,0],["v","Решив, что ты был прав, от порицанья",0,1249,0,0],["v","Никак бы не ушел я… Ты ж, свершив",0,1250,0,1],["v","Недоброе, немилое стерпи!",0,1251,0,0],["sp","<span class=\"ch\" data-ch=\"polimestor\">Полиместор</span>"],["v","О, горе мне! Рабыней побежден…",0,1252,0,0],["v","Ничтожнейшей наказан! Горе, горе!",0,1253,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Ты заслужил делами кары, знай!",0,1254,0,0],["sp","<span class=\"ch\" data-ch=\"polimestor\">Полиместор</span>"],["v","Увы! О, дети!.. О, глаза!.. О, горький!..",0,1255,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Ты мучишься… А я? Мой сын не жалок?",0,1256,0,0],["sp","<span class=\"ch\" data-ch=\"polimestor\">Полиместор</span>"],["v","Злорадствуешь, коварная раба!..",0,1257,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Я радуюсь по праву — отомстивши…",0,1260,0,1],["sp","<span class=\"ch\" data-ch=\"polimestor\">Полиместор</span>"],["v","Надолго ли? Бурливая волна…",0,1260,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Домчит меня до берегов Эллады?",0,1261,0,0],["sp","<span class=\"ch\" data-ch=\"polimestor\">Полиместор</span>"],["v","Нет, погребет: с косицы упадешь!",0,1262,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Меня в пучину сбросят силой, значит?",0,1263,0,0],["sp","<span class=\"ch\" data-ch=\"polimestor\">Полиместор</span>"],["v","Своей ногой на мачту ты взберешься.",0,1264,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Иль навяжу я крылья? Или как?",0,1265,0,0],["sp","<span class=\"ch\" data-ch=\"polimestor\">Полиместор</span>"],["v","Собакой станешь огнеокой ты.",0,1265,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Как ты узнал об этом превращенье?",0,1266,0,0],["sp","<span class=\"ch\" data-ch=\"polimestor\">Полиместор</span>"],["v","Во Фракии есть вещий Дионис.",0,1267,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Твои ж тебе предрек он тоже беды?",0,1268,0,0],["sp","<span class=\"ch\" data-ch=\"polimestor\">Полиместор</span>"],["v","Иль я б тогда в силки твои попал?",0,1269,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Живой иль мертвой образ изменю я?",0,1270,0,1],["sp","<span class=\"ch\" data-ch=\"polimestor\">Полиместор</span>"],["v","Ты? Мертвой; и кургану имя дашь.",0,1271,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Как нарекут его? По превращенью?",0,1272,0,0],["sp","<span class=\"ch\" data-ch=\"polimestor\">Полиместор</span>"],["v","«Курганом псицы» — вехой для пловцов.<a class=\"nr\" href=\"#n-k33\" data-n=\"k33\" aria-label=\"Примечание 33\">33</a>",0,1273,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Пусть будет так: ты все ж наказан мною!",0,1274,0,0],["sp","<span class=\"ch\" data-ch=\"polimestor\">Полиместор</span>"],["v","И дочь твою Кассандру умертвят…",0,1275,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Чур, чур нас — на тебя за эти речи!",0,1276,0,0],["sp","<span class=\"ch\" data-ch=\"polimestor\">Полиместор</span>"],["dir","показывая на <span class=\"ch\" data-ch=\"agamemnon\">Агамемнона</span>"],["v","Убьет — его жена, угрюмый страж.",0,1277,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Безумье да минует Тиндариду!",0,1278,0,0],["sp","<span class=\"ch\" data-ch=\"polimestor\">Полиместор</span>"],["v","Затем его — с размаху топором!",0,1279,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["dir","гневно"],["v","Эй, ты! Взбесился, что ли? Смерти просишь?",0,1280,0,1],["sp","<span class=\"ch\" data-ch=\"polimestor\">Полиместор</span>"],["v","Убей! А там — кровавая купель.",0,1280,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Убрать его, рабы! Тащите силой!<a class=\"nr\" href=\"#n-k34\" data-n=\"k34\" aria-label=\"Примечание 34\">34</a>",0,1281,0,0],["sp","<span class=\"ch\" data-ch=\"polimestor\">Полиместор</span>"],["v","Не сладко, что ли, слышать?..",0,1282,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Рот зажать!..",1,1282,0,0],["sp","<span class=\"ch\" data-ch=\"polimestor\">Полиместор</span>"],["v","Хоть на запор — все сказано!",0,1283,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Немедля",1,1283,0,0],["v","Куда-нибудь на остров из пустых,",0,1284,0,0],["v","И кинуть там! Вещун не в меру дерзок!",0,1285,0,0],["v","Телохранители уводят <span class=\"ch\" data-ch=\"polimestor\">Полиместора</span>.",0,1285,0,0],["v","А ты, Гекуба, бедная, тела",0,1286,0,0],["v","Похоронить иди… Вы разойдитесь",0,1287,0,0],["v","По господам в шатры свои, троянки…",0,1288,0,0],["v","Тот ветер, что домой зовет, слегка",0,1289,0,0],["v","Повеял уж, я вижу! До отчизны",0,1290,0,1],["v","Пусть боги нас доправят и труды",0,1291,0,0],["v","Забыть дадут под мирной сенью отчей!..",0,1292,0,0],["sp","Хор"],["dir","покидая орхестру"],["v","Туда, на берег, в шатры",0,1293,0,0],["v","Идите, подруги,",0,1294,0,0],["v","И рабской вкусите доли.",0,1295,0,0],["v","От судьбы не уйдешь никуда.",0,1296,0,0],["h1","Комментарий","comm"],["p","Хотя документальных данных о постановке трагедии не сохранилось, большинство исследователей относят ее к 424 г. до н. э.; в ст. 455-465 видят намек на «очищение» Делоса, произведенное афинянами зимой 425 г. (см.: Фукидид, III, 104), а ст. 160 и 171-173 пародируются в «Облаках» Аристофана (ст. 718 и 1165 сл.), поставленных в первой редакции в 423 г. Следовательно, для «Гекубы» остается место только в промежутке между двумя этими датами."],["p","О доеврипидовской мифологической традиции см. вступительную статью, с. 571 сл. Объединив в одной трагедии сказания о жертвоприношении Поликсены (при этом еврипидовским нововведением является готовность девушки добровольно расстаться с жизнью) и гибели Полидора, убитого во Фракии, Еврипид должен был перенести действие «Гекубы» на побережье Херсонеса Фракийского, т. е. на европейский берег Геллеспонта, куда грекам, вообще говоря, совершенно не надо было перебираться, чтобы возвратиться на родину. Кстати, и могила Ахилла должна была находиться на троянском берегу."],["p","«Гекуба» — традиционное (через латынь) написание имени героини. Сам Анненский систематически писал (в соответствии с греческим произношением) «Гекаба»."],["p","В РГАЛИ сохранилась только черновая рукопись пролога и I акта. Остальной текст печатается по правке Зелинского."],["ed","В.Н. Ярхо"],["note","k1"],["note","k2"],["note","k3"],["note","k4"],["note","k5"],["note","k6"],["note","k7"],["note","k8"],["note","k9"],["note","k10"],["note","k11"],["note","k12"],["note","k13"],["note","k14"],["note","k15"],["note","k16"],["note","k17"],["note","k18"],["note","k19"],["note","k20"],["note","k21"],["note","k22"],["note","k23"],["note","k24"],["note","k25"],["note","k26"],["note","k27"],["note","k28"],["note","k29"],["note","k30"],["note","k31"],["note","k32"],["note","k33"],["note","k34"]],"n":{"k1":["Ст. 55. Царицею заснуть…","Образ, чуждый оригиналу. У Еврипида: «…выйдя из царского дома, увидеть день рабства»."],"k2":["Ст. 98-153","Структура парода в этой трагедии своеобразна: обычно за анапестическим вступлением следует собственно хоровая часть, которая здесь отсутствует, сами же анапесты используются для пространного повествования, имеющего сюжетное назначение."],"k3":["Ст. 101. …далеко от Трои…","Поскольку действие происходит напротив Трои, то «далеко» — недосмотр переводчика. В оригинале: «изгнанную из (отлученную от) Трои»."],"k4":["Ст. 120. …вещей вакханки твоей…","Кассандры. После падения Трои Агамемнон получил в качестве пленницы-наложницы Кассандру, дочь Гекубы, наделенную пророческим даром."],"k5":["Ст. 122. Две ветви младых.","В оригинале «два Тесеида», т. е. сыновья Тесея Акамант и Демофонт (ср. «Гераклиды», ст. 119). Гомеровский эпос ничего не знает об участии этих царей в Троянском походе, но, по-видимому, уже в VI в., во время борьбы за Сигей (на малоазийском побережье), афиняне обосновывали право на область Троады заслугами своих предков в Троянской войне (ср.: Эсхил, «Евмениды», ст. 397-402)."],"k6":["Ст. 180. Горе!","Непонятно, почему опущено слово «дитя»."],"k7":["Ст. 197-215","Антистрофа и в оригинале короче строфы и дает сложную ритмическую симметрию, однако ямбическое начало ее невозможно."],"k8":["Ст. 239. Ты помнишь, царь, лазутчиком, себя…","О том, как Одиссей под видом нищего пробрался для разведки в Трою и был опознан Еленой, сообщала уже «Одиссея» (IV, 244-258). Понятно, почему Елена, стремившаяся вернуться на родину, не выдала Одиссея троянцам; участие же в его спасении Гекубы является, несомненно, нововведением Еврипида."],"k9":["Ст. 254-257. Народные витии","выпад против современных Еврипиду демагогов."],"k10":["Ст. 286. О борода…","Несколько комический оттенок придает перевод слова geneion — «подбородок», к которому прикасался молящий, прося сострадания. См.: «Медея», ст. С5-66 и примеч."],"k11":["Ст. 291-292. Свободного ль, раба ль убить, у вас ведь равный грех…","Намек на афинское уголовное право, в равной мере преследовавшее за убийство свободного и раба. Понятия «грех» в оригинале нет: речь идет о равенстве перед законом."],"k12":["Ст. 320","Одиссей выдвигает в качестве довода характерное для гомеровских героев стремление к посмертной славе; здесь, однако, «героическая» мораль находится в резком противоречии с обликом хитрого демагога."],"k13":["Ст. 340. …детей имеет…","У Одиссея был только один сын, но множественное число употреблено и в оригинале, имея обобщенное значение."],"k14":["Ст. 345. «Зевса нищих».","Зевса — покровителя молящих."],"k15":["Ст. 441-443","пропущены Анненским по непонятной причине. В переводе Зелинского:<br>О, так бы мне увидеть Спарты дочь,<br>Красу Елену: блеском глаз лучистых<br>Она сожгла все счастье Илиона!"],"k16":["Ст. 450-454. На дорийских берегах","т. е. на Пелопоннесе; на фтийских лугах — в Фессалии; Апидан — одна из фессалийских рек, впадающая в Энипей, главный приток Пенея."],"k17":["Ст. 455-465","Антистрофа I в переводе без достаточных оснований на один стих короче, чем строфа I."],"k18":["Ст. 460. Над Латоею","необычная форма от имени Лат<em>о</em> (Лет<em>о</em>)."],"k19":["Ст. 467. …Девы лучисто-колесной…","то есть Афины, восседающей на прекрасной колеснице."],"k20":["Ст. 468-472. Пеплос ее шафранный…","На пеплосе, который афинские женщины ткали для подношения Афине в праздник Великих Панафиней, изображалась битва богов с титанами."],"k21":["Ст. 643. Теперь тот спор пересмотрен…","неверный перевод. Смысл оригинала: «То решение, которое вынес Парис в споре трех богинь, привело к сражениям и убийствам»."],"k22":["Ст. 686. Выходец ада.","В оригинале — «аластор», демон бедствий и мести."],"k23":["Ст. 715. Где ж это совесть? Кто за гостя накажет тебя?","очень вольный перевод. В оригинале Гекуба взывает не к совести Полиместора (ср. примеч. к «Медее», ст. 1054), а к «справедливости», призванной карать за нарушение древнейшего закона гостеприимства (ср. ст. 790 сл., 1234 сл.). <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Медея», Ст. 1054. …совесть… не позволяет….</b> В оригинале речь идет не о совести (это понятие только появляется в V в. и встречается у Еврипида еще редко), а о тех, «кому не подобает присутствовать» при этом жертвоприношении.</span><!--/xn-->"],"k24":["Ст. 800-805. Характерное для Еврипида отступление","размышление на моральные темы, так же как ст. 814-819."],"k25":["Ст. 838. …Дедаловым искусством…","Легендарному зодчему и скульптору Дедалу греки приписывали умение создавать говорящие и движущиеся статуи."],"k26":["Ст. 886 сл","Дети Египтовы, вынудившие к браку с ними своих двоюродных сестер, дочерей Даная, были все, кроме одного, убиты в брачную ночь Данаидами (см. трагедию Эсхила «Просительницы»). На Лемносе женщины умертвили своих неверных мужей."],"k27":["Ст. 905-952. Этот стасим","первый в творчестве Еврипида образец повествовательной хоровой песни, напоминающей аттические дифирамбы Вакхилида. В более поздних трагедиях связь таких «дифирамбических стасимов» с основным содержанием трагедии становится еще менее прочной."],"k28":["Ст. 1008. Храм Афины Илионской.","О храме Афины в Трое знает уже «Илиада» (VI, 269 сл.); Гектор посылает туда Гекубу принести богине умилостивительные дары."],"k29":["Ст. 1109 сл. Дева, дочь скалистого утеса","Нимфа Эхо, от которой после ее смерти сохранился только голос, повторяющий окончания чужих слов. В недошедшей трагедии Еврипида «Андромеда» (412 г.) с участием Эхо была построена целая сцена, ставшая предметом пародии в комедии Аристофана «Женщины на празднике Фесмофорий» (Ст. 1059 сл.)."],"k30":["Ст. 1132-1182",", 1187-1237 — очередной пример ораторского агона (см. примеч. к «Медее», ст. 465-575), составленного из двух равных по объему речей. Полиместор завершает свою речь «общим местом», Гекуба, напротив, начинает свой монолог с такого же рассуждения на общую тему. <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Медея», Ст. 465-575.</b> Медея и Ясон обмениваются в споре (агоне) почти равными по объему речами, причем каждый из них излагает в строгом порядке доводы, которые должны подтвердить его правоту, и завершает свою речь кратким резюме общего характера. Ср. вступительную статью, с. 26.</span><!--/xn-->"],"k31":["Ст. 1153. …тканью эдонской…","Фракийское племя эдонян населяло область севернее Амфиполя, в низовьях р. Стримон."],"k32":["Ст. 1199 сл. …разве варвар…","Фракийцев, как и троянцев, греки считали «варварами»."],"k33":["Ст. 1273","«Курган псицы». — Под названием Киноссема, т. е. «памятник собаке», современникам Еврипида был известен мыс на восточном берегу Херсонеса Фракийского, недалеко от мест, где разыгрывается действие трагедии."],"k34":["Ст. 1275-1281","Пророчество Полиместора воспроизводит сказание об убийстве Агамемнона и Кассандры в варианте, принятом у Эсхила в «Орестее»: Агамемнон был убит Клитемнестрой в ванне."]},"mainEnd":1877,"c":[{"id":"gekuba","name":"Гекуба","role":"Вдова Приама, пленная царица Трои","intro":"Мать, потерявшая всё, — и превратившаяся в мстительницу.","arc":"Гекуба в начале — безграничное материнское горе: у неё отнимают Поликсену. Но когда она узнаёт, что последний сын, Полидор, убит фракийцем Полиместором ради золота, горе становится жаждой мести. Она хитростью ослепляет Полиместора и убивает его сыновей. Пророчество о превращении в собаку завершает этот путь от страдания к звериной ярости.","st":[{"i":131,"p":7,"l":"Пролог · явление второе","t":"Сон","d":"Тревожится из-за сна о Поликсене и Полидоре.","c":"","k":false},{"i":603,"p":32,"l":"Действие первое · явление пятое","t":"Мольба Одиссею","d":"Умоляет Одиссея пощадить Поликсену, напоминая, что когда-то спасла ему жизнь; он отказывает.","c":"","k":false},{"i":859,"p":46,"l":"Действие второе · явление седьмое","t":"Рассказ о смерти дочери","d":"Талфибий рассказывает о гибели Поликсены; Гекуба утешается её благородством.","c":"","k":false},{"i":1003,"p":53,"l":"Действие третье · явление девятое","t":"Тело Полидора","d":"В выброшенном морем теле узнаёт сына и понимает, что его убил Полиместор.","c":"Горе становится жаждой мести.","k":true},{"i":1287,"p":69,"l":"Действие третье · явление десятое","t":"Союз с Агамемноном","d":"Уговаривает Агамемнона не мешать её мести.","c":"","k":false},{"i":1468,"p":78,"l":"Исход · явление одиннадцатое","t":"Ловушка","d":"Выманивает Полиместора в шатёр рассказом о спрятанном золоте.","c":"","k":false},{"i":1876,"p":100,"l":"Исход · явление пятнадцатое","t":"Суд","d":"Перед Агамемноном обличает Полиместора; тот предсказывает ей превращение в собаку.","c":"","k":false}],"gen":"Гекуба"},{"id":"poliksena","name":"Поликсена","role":"Дочь Гекубы и Приама","intro":"Девушка, которую ахейцы приносят в жертву тени Ахилла.","arc":"Поликсена — одна из благородных жертв Еврипида: она сама предпочитает смерть рабству.","st":[{"i":603,"p":32,"l":"Действие первое · явление пятое","t":"Выбор смерти","d":"Отказывается молить Одиссея: лучше умереть, чем быть рабыней.","c":"","k":true},{"i":859,"p":46,"l":"Действие второе · явление седьмое","t":"Смерть","d":"Талфибий рассказывает, как она сама подставила грудь под нож.","c":"","k":false}],"gen":"Поликсена"},{"id":"polimestor","name":"Полиместор","role":"Царь Фракии","intro":"Друг Приама, убивший ради золота доверенного ему Полидора.","arc":"Полиместор — лицемер, который притворяется сочувствующим другом. Наказанный, он становится пророком: предсказывает гибель Агамемнона и Кассандры.","st":[{"i":1468,"p":78,"l":"Исход · явление одиннадцатое","t":"Лицемерие","d":"Лжёт Гекубе о судьбе Полидора и идёт за золотом.","c":"","k":false},{"i":1588,"p":85,"l":"Исход · явление четырнадцатое","t":"Ослеплённый","d":"Выбегает из шатра слепым, его сыновья убиты.","c":"","k":true},{"i":1876,"p":100,"l":"Исход · явление пятнадцатое","t":"Пророчество","d":"Предсказывает Гекубе превращение в собаку, Агамемнону — смерть от жены.","c":"","k":false}],"gen":"Полиместор"},{"id":"agamemnon","name":"Агамемнон","role":"Предводитель ахейцев","intro":"Царь, который сочувствует Гекубе, но боится войска.","arc":"Агамемнон здесь — осторожный политик: он не хочет открыто помогать врагам, но и не мешает мести.","st":[{"i":1287,"p":69,"l":"Действие третье · явление десятое","t":"Невмешательство","d":"Соглашается не мешать мести Гекубы.","c":"","k":false},{"i":1876,"p":100,"l":"Исход · явление пятнадцатое","t":"Суд","d":"Выслушивает обе стороны и признаёт правоту Гекубы.","c":"","k":true}],"gen":"Агамемнон"}]};
